insert into courses (id, title, number, status) values
  ('course-2', 'الدبلوم العالي المهني في القيادة الرقمية — الكورس الثاني', 2, 'published')
insert into subjects (id, course_id, "order", title, short_title, icon, accent, status, description) values
  ('ai-data', 'course-2', 1, 'الذكاء الاصطناعي وتحليل البيانات', 'الذكاء الاصطناعي', '🤖', '#2E6E5E', 'published', 'من أساسيات النماذج اللغوية الكبيرة إلى الاستخدام العملي لأدوات الذكاء الاصطناعي التوليدي (كلود Claude) في العمل الحكومي والإداري.'),
  ('legal-regulatory', 'course-2', 2, 'الثقافة القانونية والتنظيمية', 'الثقافة القانونية', '⚖️', '#7A5A16', 'published', 'الإطار القانوني والتنظيمي الحاكم للعمل المؤسسي والتحول الرقمي: التشريعات، اللوائح، الامتثال، حماية البيانات، والمسؤولية القانونية في البيئة الرقمية.'),
  ('cybersecurity-governance', 'course-2', 3, 'حوكمة الأمن السيبراني', 'الأمن السيبراني', '🛡️', '#123B4A', 'published', 'حوكمة الأمن السيبراني على مستوى المؤسسة: السياسات، الأدوار والمسؤوليات، الأطر المرجعية، إدارة الحوادث، وقياس النضج السيبراني.'),
  ('innovation-project-management', 'course-2', 4, 'الابتكار وإدارة المشاريع', 'الابتكار والمشاريع', '💡', '#B8891B', 'published', 'من الفكرة إلى التنفيذ: أنواع الابتكار وأدواته، ودورة حياة المشروع، ونطاقه وزمنه وكلفته، والمنهجيات التقليدية والرشيقة في إدارة المشاريع الرقمية.'),
  ('risk-management', 'course-2', 5, 'إدارة المخاطر', 'إدارة المخاطر', '📊', '#B23A2E', 'published', 'منهجية متكاملة لتحديد المخاطر وتحليلها وتقييمها ومعالجتها ومراقبتها، وبناء سجل مخاطر وثقافة مؤسسية واعية بالمخاطر في بيئة التحول الرقمي.')
insert into lectures (id, subject_id, number, title, date, status, demo, description, objectives) values
  ('ai-l1', 'ai-data', 1, 'الأسبوع الأول — كلود Claude: مدخل إلى الذكاء الاصطناعي التوليدي', '2026-09-01', 'published', FALSE, 'كلود نموذج لغوي كبير (LLM) يتوقع الكلمة التالية بناءً على أنماط تعلّمها من نصوص هائلة — وهذا التوقّع ليس تفكيرًا بالمعنى البشري. يمر أي طلب بأربع مراحل: الأمر (Prompt) — الجملة التي تكتبها للبرنامج وتوضّح فيها ما تريده بالضبط، ثم التقطيع (Tokenization) —…', '["الأساسيات","التعرّف على كلود","البداية العملية","شات، كوورك، وكود: شنو الفرق؟","هندسة الأوامر","المشاريع والملحقات والمهارات"]'::jsonb),
  ('ai-l2', 'ai-data', 2, 'الأسبوع الثاني — جولة داخل كلود: الواجهات والإعدادات', '2026-09-01', 'published', FALSE, 'Chat: محادثة جديدة، أرشيف كل نقاشاتك السابقة قابل للبحث، ورفع الملفات والصور والمحادثة الصوتية. Projects: ساحة محفوظة لمعلومات وملفات ثابتة لموضوع معيّن — تعليمات دائمة، ملفات مرجعية، ومحادثات ضمن سياق المشروع. Artifacts: ناتجة تفاعلية تُنتج نتيجة واحدة تعرض نفسك.', '["واجهات الاستخدام","الإعدادات من الهاتف","الحوكمة والاستخدام الآمن"]'::jsonb),
  ('lg-l1', 'legal-regulatory', 1, 'التحول الإلكتروني وأثره في الإدارة والوظيفة العامة', '2026-09-01', 'published', FALSE, 'التحول الرقمي وتطور البيئة القانونية: مفهوم التطور الإلكتروني في الإدارة العامة، ونتائج الانتقال من الإدارة التقليدية إلى الإدارة الإلكترونية، والحكومة الإلكترونية وعلاقتها بالوظيفة العامة، والأثر القانوني لهذا التحول ومعوقاته.', '["فهم مفهوم التطور الإلكتروني في مجال الإدارة العامة.","إدراك نتائج الانتقال من الإدارة التقليدية إلى الإدارة الإلكترونية.","التعرّف على الحكومة الإلكترونية وعلاقتها بالوظيفة العامة وتطبيقاتها.","تحديد الأثر القانوني للتحول الإلكتروني في الوظيفة العامة.","إدراك دور الرقابة والشفافية في الإدارة الإلكترونية ومعوقات التحول."]'::jsonb),
  ('lg-l3', 'legal-regulatory', 2, 'الثقافة القانونية والتنظيمية في عصر التحول الرقمي والحكومة الرقمية والمشروعية', '2026-09-02', 'published', FALSE, 'التمييز بين الحكومة الإلكترونية والحوكمة الإلكترونية، ومبدأ المشروعية في الإدارة الرقمية بأبعاده الخمسة، والقرار الإداري الإلكتروني والمؤتمت، والمسؤولية عن القرارات الإلكترونية وأخطاء الخوارزميات، وحق الفرد في الطعن، والرقابة القضائية على الإدارة الرقمية.', '["التمييز بين الحكومة الإلكترونية والحوكمة الإلكترونية.","شرح مبدأ المشروعية في الإدارة الرقمية بأبعاده الخمسة: الاختصاص، الشكل والإجراءات، السبب، المحل، الغاية.","التمييز بين القرار الإداري الإلكتروني والقرار الإداري المؤتمت.","تحليل صور المسؤولية عن القرارات الإلكترونية: مسؤولية الإدارة، والموظف، ومصمم النظام.","إدراك أهمية الشفافية وحجية السجل الإلكتروني وحق الطعن بالقرار الإلكتروني.","فهم أثر الأمن السيبراني والرقابة القضائية على مشروعية القرار الإداري الرقمي."]'::jsonb),
  ('lg-l4', 'legal-regulatory', 3, 'المعاملات والوثائق والتوقيع الإلكتروني', '2026-09-09', 'published', FALSE, 'قانون التوقيع الإلكتروني والمعاملات الإلكترونية العراقي رقم (78) لسنة 2012: مفهوم المعاملة الإلكترونية ومبادئها الحاكمة ونطاق تطبيق القانون، الوثيقة الإلكترونية وعناصرها الفنية وسلسلة الحيازة الرقمية، التوقيع الإلكتروني وحجيته في الإثبات والفرق بينه وبين التوقيع الرقمي، الأرشفة الإلكترونية القانونية، ومعايير تقييم الدليل الإلكتروني أمام القضاء.', '["تحديد المقصود بالمعاملة الإلكترونية ونطاق تطبيق القانون العراقي واستثناءاته.","شرح المبادئ الثلاثة الحاكمة للمعاملات الإلكترونية: عدم التمييز، التكافؤ الوظيفي، الحياد التكنولوجي.","تحديد العناصر الفنية للوثيقة الإلكترونية وسلسلة الحيازة الرقمية.","تعريف التوقيع الإلكتروني وبيان شروط حجيته الإثباتية وفق المادتين (4) و(5) من القانون العراقي.","التمييز بين التوقيع الإلكتروني والتوقيع الرقمي (Digital Signature).","إدراك متطلبات الأرشفة الإلكترونية القانونية والفنية.","تطبيق معايير تقييم الدليل الإلكتروني الخمسة على نزاع عقد إلكتروني."]'::jsonb),
  ('lg-l2', 'legal-regulatory', 4, 'الامتثال التنظيمي وحماية البيانات', '2026-08-18', 'published', TRUE, 'مفهوم الامتثال، ومسؤوليات الجهة عن البيانات الشخصية، ومخاطر عدم الامتثال ونتائجه.', '["تعريف الامتثال التنظيمي ومكوناته.","التعرّف على مبادئ حماية البيانات الشخصية.","تحديد المسؤولية عند وقوع مخالفة."]'::jsonb),
  ('cs-l1', 'cybersecurity-governance', 1, 'مقدمة في الأمن السيبراني وحوكمة أمن المعلومات', '2026-09-02', 'published', FALSE, 'مدخل شامل إلى مفاهيم الأمن السيبراني الأساسية (التهديدات، الفاعلون، مثلث CIA)، ومدخل إلى حوكمة أمن المعلومات وأركانها وأصحاب المصلحة فيها ودورها في حماية المؤسسات.', '["تعريف الأمن السيبراني وتوضيح أهميته للمؤسسات والأفراد.","شرح مثلث CIA والمبادئ الأساسية لأمن المعلومات.","تصنيف أبرز التهديدات السيبرانية والفاعلين وراءها.","تعريف حوكمة أمن المعلومات والتمييز بينها وبين الإدارة التنفيذية.","التعرّف على أركان الحوكمة وأصحاب المصلحة الرئيسيين."]'::jsonb),
  ('cs-l3', 'cybersecurity-governance', 2, 'إطار NIST CSF 2.0 للأمن السيبراني ووظيفة الحوكمة (Govern)', '2026-09-08', 'published', FALSE, 'نشأة معهد NIST وتطور إطار CSF عبر إصداراته الثلاثة، الوظائف الست الأساسية للإطار، الفئات الست التفصيلية لوظيفة الحوكمة (GV Categories)، ومستويات التطبيق والملفات التعريفية وتحليل الفجوة.', '["فهم الجذور التاريخية والطبيعة التنظيمية لمعهد NIST وتطور إطار CSF عبر إصداراته الثلاثة.","شرح المستجدات الجوهرية في CSF 2.0، وأبرزها شمولية النطاق واستحداث وظيفة الحوكمة.","تعداد الوظائف الست الأساسية للإطار وموقع كل منها في دورة الأمن السيبراني.","تحليل الفئات الست التفصيلية لوظيفة الحوكمة (GV Categories).","التمييز بين مستويات تطبيق الإطار (Tiers) والملفات التعريفية (Profiles) وتحليل الفجوة."]'::jsonb),
  ('cs-l2', 'cybersecurity-governance', 3, 'السياسات وإدارة الحوادث السيبرانية', '2026-08-19', 'published', TRUE, 'بناء السياسات الأمنية، وتصنيف الحوادث، ومراحل الاستجابة، والتعافي والدروس المستفادة.', '["صياغة سياسة أمنية قابلة للتطبيق والقياس.","التعرّف على مراحل الاستجابة للحوادث.","إدراك أهمية التوثيق والدروس المستفادة."]'::jsonb),
  ('ip-l1', 'innovation-project-management', 1, 'الابتكار وإدارة المشاريع الرقمية ودور الابتكار في الاقتصاد الرقمي', '2026-09-01', 'published', FALSE, 'التحول من الاقتصاد التقليدي إلى الاقتصاد الرقمي وأثره في ظهور نماذج أعمال ومنصات ومشاريع قائمة على البيانات والتكنولوجيا، ومفهوم الابتكار والفرق بينه وبين الإبداع والاختراع وريادة الأعمال، والعلاقة التكاملية بين الابتكار وإدارة المشاريع الرقمية في خلق القيمة الاقتصادية.', '["إدراك أثر التحول من الاقتصاد التقليدي إلى الاقتصاد الرقمي على نماذج الأعمال.","تعريف الابتكار بوصفه تحويل الأفكار والمعارف إلى منتجات وخدمات وعمليات تحقق قيمة قابلة للقياس.","التمييز بين الإبداع والاختراع والابتكار وريادة الأعمال.","فهم العلاقة التكاملية بين الابتكار وإدارة المشاريع الرقمية والاقتصاد الرقمي.","إدراك اختلاف مهارات وأدوات إدارة المشاريع الرقمية عن إدارة المشاريع التقليدية."]'::jsonb),
  ('ip-l3', 'innovation-project-management', 2, 'نظريات ونماذج الابتكار الحديثة: الأطر النظرية والتطبيقات الاستراتيجية', '2026-09-02', 'published', FALSE, 'استعراض معمّق لأبرز نظريات ونماذج الابتكار: ثنائية الابتكار الجذري والتدريجي، والابتكار المفتوح بأبعاده الثلاثة، ونموذج الابتكار المستمر، وكيفية تكامل هذه الأطر لتحقيق الميزة التنافسية المستدامة.', '["التمييز بين الابتكار التدريجي والابتكار الجذري من حيث المخاطر والأسواق والأساس التكنولوجي.","شرح نموذج الابتكار المفتوح لهنري تشيسبرو وأبعاده الثلاثة (Inbound وOutbound وCoupled).","فهم نموذج الابتكار المستمر وعلاقته بفلسفات Kaizen والرشاقة المؤسسية والإدارة الهزيلة.","تحليل كيفية تكامل نماذج الابتكار الثلاثة لتحقيق ميزة تنافسية مستدامة."]'::jsonb),
  ('ip-l2', 'innovation-project-management', 3, 'دورة حياة المشروع والقيود الثلاثية', '2026-08-20', 'published', TRUE, 'مراحل المشروع الخمس، وثلاثية النطاق والزمن والكلفة، والفرق بين المنهجية التقليدية والرشيقة.', '["تحديد مراحل دورة حياة المشروع.","فهم أثر تغيير أحد أضلاع القيود الثلاثية على البقية.","المقارنة بين المنهج التقليدي والرشيق واختيار الأنسب."]'::jsonb),
  ('rm-l1', 'risk-management', 1, 'الفصل الأول — لماذا لا تكفي معرفة الخطر؟', '2026-09-09', 'published', FALSE, 'تفكيك مفهوم الخطر إلى المُخطِر والتعرّض وقابلية التأثر، مقارنة تعريفات الخطر المرجعية (ISO 31000، الدليل البريطاني، الدليل السعودي)، التمييز بين إدارة المخاطر والرقابة والتدقيق والامتثال، الفرق بين المخاطرة وعدم اليقين والغموض، والتمييز بين التهوّر والجمود والمخاطرة المحسوبة.', '["التمييز بين الخطر والمشكلة والأزمة.","تفكيك مفهوم الخطر إلى عناصره الثلاثة: المُخطِر، التعرّض، وقابلية التأثر.","صياغة خطر بطريقة عملية قابلة لاتخاذ القرار بدلاً من مجرد عنوان.","التمييز بين إدارة المخاطر والرقابة الداخلية والتدقيق الداخلي والامتثال.","التفريق بين المخاطرة والغموض وعدم اليقين، وإدراك «وهم السيطرة».","تطبيق «اختبار الأثر القراري» لقياس الأثر الحقيقي لمنظومة إدارة المخاطر."]'::jsonb),
  ('rm-l2', 'risk-management', 2, 'تقييم المخاطر واستراتيجيات المعالجة', '2026-08-21', 'published', TRUE, 'مصفوفة المخاطر، وتصنيف المخاطر حسب الأولوية، واستراتيجيات المعالجة الأربع، وسجل المخاطر.', '["بناء مصفوفة مخاطر وتحديد الأولويات.","اختيار استراتيجية المعالجة المناسبة لكل خطر.","إعداد سجل مخاطر قابل للمتابعة."]'::jsonb)
insert into summaries (id, subject_id, lecture_id, title, date, status, demo, key_points, concepts, terms) values
  ('ai-s1', 'ai-data', 'ai-l1', 'الأسبوع الأول — الأساسيات', '2026-09-01', 'published', FALSE, '["كلود نموذج لغوي كبير يتوقّع الكلمة التالية بناءً على أنماط تعلّمها — لا يفكّر كالإنسان.","رحلة الأمر: Prompt ← Tokenization ← Embeddings ← Generation.","افترض دائمًا احتمال «الهلوسة» وتحقّق من أي معلومة حسّاسة قبل اعتمادها.","أربع طرق للوصول: كلود كود (برمجة)، كلود كوورك (مهام كبيرة وملفات)، المتصفح، وتطبيق الجوال.","القواعد الأربع لأمر ناجح: الموقف، المهمة، الشكل، ثم مثال.","هايكو للسرعة، سونيت للتوازن، أوبس للدقة، والتفكير الممتد للتحليل العميق.","عقلية التكرار (بناء تدريجي بالملاحظات) أفضل من انتظار نتيجة كاملة من أمر واحد."]'::jsonb, '[{"term":"نموذج لغوي كبير (LLM)","definition":"برنامج «قرأ» كمية هائلة من النصوص ويتوقع الكلمة التالية المناسبة، من دون أن «يفهم» بالمعنى الإنساني."},{"term":"الأمر / الطلب (Prompt)","definition":"الجملة التي تكتبها للبرنامج توضّح فيها ما تريد بالضبط."},{"term":"التقطيع (Tokenization)","definition":"تقسيم جملتك إلى قطع صغيرة يتعامل معها البرنامج."},{"term":"التمثيل الرقمي (Embeddings)","definition":"تحويل كل قطعة نص إلى أرقام تقارب معناها."},{"term":"نافذة السياق (Context Window)","definition":"كمية النص التي يقدر البرنامج يتذكرها بنفس المحادثة."},{"term":"الهلوسة / الاختلاق (Hallucination)","definition":"إعطاء معلومة غير دقيقة بثقة تامة وكأنها صحيحة."},{"term":"شات / كوورك / كود","definition":"محادثة سريعة، أو تنفيذ مهام أكبر باللمّات، أو أداة برمجة كاملة الوظيفة."}]'::jsonb, '["نموذج لغوي كبير (LLM)","الأمر / الطلب (Prompt)","التقطيع (Tokenization)","التمثيل الرقمي (Embeddings)","نافذة السياق (Context Window)","الهلوسة / الاختلاق (Hallucination)","شات / كوورك / كود"]'::jsonb),
  ('ai-s2', 'ai-data', 'ai-l2', 'الأسبوع الثاني — الواجهات والإعدادات', '2026-09-01', 'published', FALSE, '["Chat لمهمة سريعة، Projects لموضوع متكرر بذاكرة دائمة، Artifacts لنتيجة تفاعلية مستقلة.","Cowork يدير مهامًا أكبر عبر حالات: Working، Needs input، Ready for review، Completed، Archived.","Dispatch يفوّض جزءًا من المهمة لفرع مستقل يعمل بالخلفية.","المهام المجدولة (Scheduled runs) تنفّذ تلقائيًا حسب موعد محدَّد ولها سجل تنفيذات.","الإعدادات الأساسية: Profile، Billing/Usage، Capabilities، Connectors، Skills.","الحوكمة: تصنيف البيانات (عام/داخلي/سرّي)، إخفاء هوية البيانات الشخصية PII، وإبقاء الإشراف البشري قبل أي اعتماد.","مراجعة الجلسات النشطة (Active sessions) دوريًا إجراء أمني ضروري."]'::jsonb, '[{"term":"Cowork","definition":"واجهة إدارة المهام الكبيرة التي تصل لملفاتك وتعمل بالخلفية."},{"term":"Dispatch","definition":"إرسال مهمة تُنفَّذ بعيدًا ثم تُعرض عليك نتيجتها."},{"term":"Session (الجلسة)","definition":"نافذة عمل مستقلة لها سياقها وحالتها الخاصة."},{"term":"Needs input","definition":"حالة مهمة متوقفة بانتظار قرار منك."},{"term":"Ready for review","definition":"المهمة أُنجزت وتنتظر مراجعة اعتمادك."},{"term":"Scheduled runs (المهام المجدولة)","definition":"مهام تعمل تلقائيًا في مواعيد محدَّدة."},{"term":"Trigger (المشغّل)","definition":"الشرط أو الموعد الذي يُطلِق المهمة المجدولة."},{"term":"Capabilities (القدرات)","definition":"مزايا كلود التي تُفعَّل أو تُطفَأ من الإعدادات."},{"term":"Connectors (الموصلات)","definition":"الحسابات الخارجية المرتبطة مثل Drive والبريد والتقويم."},{"term":"Trusted devices (الأجهزة الموثوقة)","definition":"أجهزة تم التحقق منها قبل السماح لها بالوصول لملفاتك."},{"term":"Active sessions (الجلسات النشطة)","definition":"كل جهاز مفتوح حاليًا على حسابك مع موقعه وتاريخه."},{"term":"Export data (تصدير البيانات)","definition":"تنزيل أرشيف كامل لمحاوراتك ومشاريعك."},{"term":"Auto-reload (إعادة التمحون التلقائي)","definition":"شراء رصيد استخدام تلقائيًا عند اقترابه من النفاد."},{"term":"Skills (المهارات)","definition":"أسلوب عمل جاهز تُخبِر كلود عند الحاجة تشغيله أو تنشرها بنفسك."}]'::jsonb, '["Cowork","Dispatch","Session (الجلسة)","Needs input","Ready for review","Scheduled runs (المهام المجدولة)","Trigger (المشغّل)","Capabilities (القدرات)","Connectors (الموصلات)","Trusted devices (الأجهزة الموثوقة)","Active sessions (الجلسات النشطة)","Export data (تصدير البيانات)","Auto-reload (إعادة التمحون التلقائي)","Skills (المهارات)"]'::jsonb),
  ('lg-s1', 'legal-regulatory', 'lg-l1', 'ملخص المحاضرة الأولى — التحول الرقمي وتطور البيئة القانونية', '2026-09-01', 'published', FALSE, '["مفهوم التطور الإلكتروني في مجال الإدارة العامة.","نتائج الانتقال من الإدارة التقليدية إلى الإدارة الإلكترونية.","الحكومة الإلكترونية وعلاقتها بالوظيفة العامة.","تطبيقات التطور الإلكتروني في الوظيفة العامة.","الأثر القانوني للتحول الإلكتروني في الوظيفة العامة.","أثر التطور الإلكتروني في كفاءة المرفق العام.","الرقابة والشفافية في الإدارة الإلكترونية.","المعوقات القانونية والإدارية للتحول الإلكتروني.","من التحول الإلكتروني إلى الذكاء الاصطناعي."]'::jsonb, '[{"term":"التحول الإلكتروني","definition":"انتقال الإدارة من الأساليب الورقية التقليدية إلى الوسائل الرقمية في أداء وظائفها."},{"term":"الحكومة الإلكترونية","definition":"تقديم الخدمات العامة عبر الوسائط الرقمية وأثر ذلك في الوظيفة العامة."},{"term":"المرفق العام","definition":"النشاط الذي تديره الإدارة لتلبية حاجة عامة، وتتأثر كفاءته بالتحول الإلكتروني."}]'::jsonb, '["الإدارة الإلكترونية","الوظيفة العامة","الشفافية","الرقابة الإدارية","الأثر القانوني"]'::jsonb),
  ('lg-s2', 'legal-regulatory', 'lg-l2', 'ملخص المحاضرة الرابعة — الامتثال وحماية البيانات', '2026-08-19', 'published', TRUE, '["الامتثال التزام مستمر وليس إجراءً لمرة واحدة.","جمع البيانات الشخصية يجب أن يقتصر على الغرض المحدّد له.","الشفافية تجاه صاحب البيانات ركن أساسي في أي معالجة.","عدم الامتثال يرتّب مسؤولية إدارية وقد يرتّب مسؤولية جزائية."]'::jsonb, '[{"term":"الامتثال التنظيمي","definition":"التزام الجهة بالقوانين واللوائح والسياسات المنطبقة على نشاطها."},{"term":"تحديد الغرض","definition":"مبدأ يقضي بجمع البيانات لغرض مشروع ومحدّد ومُعلن مسبقاً."},{"term":"تقليل البيانات","definition":"الاكتفاء بأقل قدر من البيانات يحقق الغرض."}]'::jsonb, '["البيانات الشخصية","المعالجة","المسؤول عن البيانات","الإفصاح"]'::jsonb),
  ('lg-s3', 'legal-regulatory', 'lg-l1', 'مفهوم التحول الإلكتروني', '2026-09-01', 'published', FALSE, '["التطور الإلكتروني هو توظيف تكنولوجيا المعلومات والاتصالات في أداء وظائف الإدارة العامة.","يقوم على عنصرين: تقني (أجهزة وبرامج وشبكات) وبشري (موظفون ومتخصصون).","التقنية وسيلة لأداء النشاط الإداري، وليست بديلًا عن القانون الذي يحكمه.","الحكومة الإلكترونية ليست حكومة جديدة، بل الحكومة ذاتها تؤدي وظائفها بوسيلة إلكترونية."]'::jsonb, '[{"term":"الإدارة الإلكترونية","definition":"استخدام الحاسوب والبرامج وشبكات الاتصال في أداء وظائف الإدارة العامة ومهامها."},{"term":"الحكومة الإلكترونية","definition":"استخدام تقنيات المعلومات والاتصالات لإنجاز الأعمال الحكومية وتقديم الخدمات وتبادل البيانات."},{"term":"العنصر التقني","definition":"أجهزة الحاسوب والبرامج وقواعد البيانات والشبكات والتطبيقات الإلكترونية."},{"term":"العنصر البشري","definition":"الموظفون والمتخصصون القادرون على تشغيل الأنظمة الإلكترونية وتوظيفها وظيفيًا."},{"term":"الأرشفة الإلكترونية","definition":"حفظ الوثائق والمستندات في وسائط إلكترونية بدل الملفات الورقية."},{"term":"أمن المعلومات","definition":"مجموعة الإجراءات التي تضمن سرّية البيانات وسلامتها والتحقق من هوية المستخدم وصلاحياته."},{"term":"استمرار المرفق العام بانتظام واطراد","definition":"مبدأ يوجب على المرفق العام أداء خدماته باستمرار دون انقطاع، بما في ذلك عند الاعتماد على الأنظمة الإلكترونية."}]'::jsonb, '["الإدارة الإلكترونية","الحكومة الإلكترونية","العنصر التقني","العنصر البشري","الأرشفة الإلكترونية","أمن المعلومات","استمرار المرفق العام بانتظام واطراد"]'::jsonb),
  ('lg-s4', 'legal-regulatory', 'lg-l1', 'التطبيقات والأثر القانوني', '2026-09-01', 'published', FALSE, '["من أبرز التطبيقات: الرواتب، الإجازات، الترقيات، شؤون الموظفين، المشتريات، المراسلات، والأرشفة الإلكترونية.","دقة البيانات الإلكترونية وسلامتها وحمايتها مسألة قانونية لا تقنية فقط، لأنها ترتّب حقوقًا والتزامات.","تثير البيئة الإلكترونية أسئلة قانونية جديدة: قيمة المستند الإلكتروني، إثبات هوية المستخدم، الاعتماد على المراسلات الإلكترونية في الإثبات، ومسؤولية إتلاف البيانات.","أمن المعلومات يتطلب: التحقق من الهوية، التأكد من الصلاحية، منع التعديل غير المصرّح به، الحفاظ على السرّية، والحماية من الإتلاف."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('lg-s5', 'legal-regulatory', 'lg-l1', 'الكفاءة والرقابة والمعوقات', '2026-09-01', 'published', FALSE, '["التحول الإلكتروني يرفع كفاءة المرفق العام: سرعة الإنجاز، تقليل الروتين، تحسين اتخاذ القرار، وتعزيز الرقابة.","في المقابل يخلق تحديًا يتعلق باستمرار المرفق العام بانتظام واطراد عند توقف الأنظمة أو الاختراق.","الرقابة الإلكترونية تزيد الشفافية، لكن يجب موازنتها مع حماية خصوصية الموظف.","المعوقات أربعة أنواع: إدارية وتنظيمية، قانونية، تقنية ومالية، وبشرية."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('lg-s6', 'legal-regulatory', 'lg-l1', 'من التحول الإلكتروني إلى الذكاء الاصطناعي', '2026-09-01', 'published', FALSE, '["استخدام الذكاء الاصطناعي في الوظيفة العامة مرحلة أكثر تقدمًا من الإدارة الإلكترونية.","يثير تساؤلات قانونية جديدة: المسؤولية عن خطأ النظام الذكي، حدود الرقابة البشرية، تحيّز الخوارزميات، وحماية البيانات.","القاعدة الأساسية: التحول الرقمي يغيّر الوسيلة، لا يلغي خضوع الإدارة والموظف للقانون."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('lg-s7', 'legal-regulatory', 'lg-l3', 'مبدأ المشروعية والمسؤولية عن القرار الإلكتروني', '2026-09-02', 'published', FALSE, '["الحكومة الإلكترونية تعني الاستخدام التكاملي لتقنية المعلومات لتسريع التعاملات، بينما الحوكمة الإلكترونية أشمل وتتأثر بمفاهيم الحكم الراشد.","لا تختلف مشروعية العمل الإداري بسبب الوسيلة: القرار الإلكتروني يخضع لنفس شروط مشروعية القرار الورقي.","أبعاد المشروعية الخمسة: الاختصاص، الشكل والإجراءات، السبب، المحل، الغاية.","المنصة الإلكترونية لا تملك سلطة إدارية بذاتها، وإنما هي أداة تقنية لممارسة سلطة يملكها شخص أو جهة إدارية بموجب القانون.","أتمتة القرار لا تعني انعدام المسؤولية؛ فالخوارزمية ليست بديلاً عن مبدأ المشروعية ولا شخصاً قانونياً يتحمل المسؤولية.","المسؤولية عن القرار الإلكتروني قد تقع على الإدارة، أو الموظف، أو الجهة المصمّمة للنظام، بحسب مصدر الخطأ."]'::jsonb, '[{"term":"مبدأ المشروعية","definition":"خضوع الإدارة في جميع تصرفاتها وأعمالها للقانون، بحيث لا تتخذ قراراً إلا في حدود الاختصاصات الممنوحة لها قانوناً."},{"term":"القرار الإداري المؤتمت","definition":"القرار الذي يُنتج كلياً أو جزئياً بواسطة نظام إلكتروني وفق مجموعة من القواعد أو الخوارزميات."},{"term":"الخطأ الخوارزمي","definition":"خطأ ناتج عن تصميم الخوارزمية بطريقة تؤدي إلى نتيجة غير عادلة أو غير صحيحة قانوناً، رغم صحتها التقنية."},{"term":"حجية السجل الإلكتروني","definition":"قدرة أدوات مثل التوقيع الإلكتروني والطابع الزمني وسجل العمليات على إثبات صدور القرار فعلاً وتحديد من اتخذه ومتى وكيف."}]'::jsonb, '["الحوكمة الإلكترونية","الحكومة الإلكترونية","القرار الإداري الإلكتروني","الامتثال القانوني","الرقابة القضائية"]'::jsonb),
  ('lg-s8', 'legal-regulatory', 'lg-l4', 'المعاملات والوثائق والتوقيع الإلكتروني', '2026-09-09', 'published', FALSE, '["المعاملة الإلكترونية = إجراء قانوني أو إداري أو تجاري يتم كلياً أو جزئياً باستخدام وسيلة إلكترونية، وتشمل نطاقاً أوسع من العقد الإلكتروني وحده.","المبادئ الثلاثة الحاكمة: عدم التمييز، التكافؤ الوظيفي، والحياد التكنولوجي.","القانون العراقي رقم (78) لسنة 2012 واسع النطاق لكنه يستثني مسائل الأحوال الشخصية والعقارات وإجراءات القضاء وما يشترط توثيقه لدى الكاتب العدل.","الوثيقة الإلكترونية ليست مجرد ملف PDF، وتقييمها يقوم على: سلامة المحتوى، الأصالة، إمكانية التحقق، إمكانية الوصول، قابلية الاسترجاع، وسلسلة الحيازة الرقمية.","التوقيع الإلكتروني علامة شخصية متفردة تدل على نسبتها للموقّع، وحجيته الإثباتية تتوقف على ارتباطه بالموقّع وسيطرته على وسيلة الإنشاء وإمكانية كشف التغيير (المادة 5).","كل توقيع رقمي يمكن أن يكون توقيعاً إلكترونياً، لكن ليس كل توقيع إلكتروني توقيعاً رقمياً.","الأرشفة الإلكترونية مسألة قانونية لا تقنية فقط، وتقوم على سلامة المحتوى والتحكم بالصلاحيات وسجل الدخول والتعديل والنسخ الاحتياطي والتشفير.","الدليل الإلكتروني لا تُقاس قوته من شكله الإلكتروني، وإنما من درجة موثوقية البيئة التقنية والقانونية التي أنشأته وحفظته."]'::jsonb, '[{"term":"مبدأ التكافؤ الوظيفي","definition":"إذا استطاعت الوسيلة الإلكترونية تحقيق الوظيفة التي كان يؤديها المحرر الورقي، فيمكن منحها أثراً قانونياً مماثلاً."},{"term":"سلسلة الحيازة الرقمية","definition":"السجل الدقيق الذي يتتبع الدليل الإلكتروني من لحظة جمعه وتوثيقه وحتى عرضه أمام المحكمة، لضمان سلامته وعدم التلاعب به."},{"term":"التوقيع الرقمي مقابل التوقيع الإلكتروني","definition":"التوقيع الإلكتروني مفهوم قانوني واسع، بينما التوقيع الرقمي مفهوم تقني أخص يعتمد عادة على تقنيات التشفير بالمفتاح العام."},{"term":"معايير تقييم الدليل الإلكتروني","definition":"الأصالة، السلامة، الموثوقية، إمكانية التحقق، وسلسلة الحيازة — معايير قضائية لتقدير حجية الدليل الرقمي."}]'::jsonb, '["المعاملة الإلكترونية","الوثيقة الإلكترونية","التوقيع الإلكتروني","التوقيع الرقمي","الأرشفة الإلكترونية","سلسلة الحيازة الرقمية"]'::jsonb),
  ('cs-s1', 'cybersecurity-governance', 'cs-l1', 'ملخص المحاضرة الأولى — الأمن السيبراني وحوكمته', '2026-09-02', 'published', FALSE, '["الأمن السيبراني حماية للأنظمة والشبكات والبيانات وسلوك المستخدمين من الوصول غير المصرح به والهجمات والأضرار.","ثلاثية CIA: السرية والسلامة والتوافر، ركيزة أمن المعلومات الأساسية، وتكمّلها المصادقة والتفويض وعدم الإنكار والمساءلة.","أبرز التهديدات: البرمجيات الخبيثة، برمجيات الفدية، التصيد الاحتيالي، حجب الخدمة، الهندسة الاجتماعية، والتهديدات الداخلية.","الحوكمة تحدّد «من يقرر ومن يُسأل»، والإدارة تنفّذ وتشغّل يومياً.","الأركان الستة للحوكمة: القيادة والالتزام، الهيكل التنظيمي، السياسات والمعايير، إدارة المخاطر، الامتثال، وقياس الأداء."]'::jsonb, '[{"term":"السرية (Confidentiality)","definition":"ضمان عدم اطلاع غير المصرح لهم على المعلومات الحساسة."},{"term":"السلامة (Integrity)","definition":"ضمان دقة البيانات واكتمالها وعدم التلاعب بها دون تصريح."},{"term":"التوافر (Availability)","definition":"ضمان وصول المستخدمين المخوّلين للمعلومات والأنظمة عند الحاجة."},{"term":"المساءلة (Accountability)","definition":"ربط كل نشاط بجهة أو شخص مسؤول عنه، والمهمة التي تربط الأمن بالحوكمة."},{"term":"حوكمة أمن المعلومات","definition":"الإطار الذي يحدد من خلاله مجلس الإدارة والإدارة التنفيذية التوجهات والأهداف والمسؤوليات المتعلقة بأمن المعلومات."}]'::jsonb, '["الخطر (Risk)","التهديد (Threat)","الثغرة (Vulnerability)","CISO","الامتثال (Compliance)","NIST CSF","ISO/IEC 27001"]'::jsonb),
  ('cs-s3', 'cybersecurity-governance', 'cs-l3', 'ملخص المحاضرة الثانية — إطار NIST CSF 2.0 ووظيفة الحوكمة', '2026-09-08', 'published', FALSE, '["إطار NIST CSF تطوّر عبر ثلاث إصدارات: 1.0 (2014، البنية التحتية الحيوية)، 1.1 (2018، قياس المخاطر وسلسلة التوريد)، 2.0 (2024، شمولية النطاق واستحداث وظيفة الحوكمة).","الوظائف الست الأساسية: الحوكمة، التعرّف، الحماية، الكشف، الاستجابة، والتعافي — وتوجّه الحوكمة الوظائف الخمس الأخرى.","وظيفة الحوكمة تضم ست فئات فرعية (GV Categories): السياق التنظيمي (GV.OC)، استراتيجية إدارة المخاطر (GV.RM)، الأدوار والمسؤوليات (GV.RR)، السياسات (GV.PO)، الرقابة (GV.OV)، وسلسلة التوريد (GV.SC).","مستويات تطبيق الإطار الأربعة (Tiers) تقيس نضج إدارة المخاطر من الجزئي إلى المتكيف.","مقارنة الملف الحالي بالملف المستهدف (Profiles) هي أساس تحليل الفجوة وبناء خارطة الطريق."]'::jsonb, '[{"term":"الحوكمة (Govern)","definition":"الوظيفة السادسة المستحدثة في CSF 2.0، تحدد الاستراتيجية وشهية المخاطر والسياسات وتوجّه بقية الوظائف."},{"term":"شهية المخاطر (Risk Appetite)","definition":"حدود مستويات المخاطر السيبرانية التي تقبل الإدارة العليا تحمّلها لتحقيق أهدافها المؤسسية."},{"term":"سقف التحمل (Risk Tolerance)","definition":"الحد الأقصى للانحراف المقبول عن شهية المخاطر المعتمدة."},{"term":"مستويات التطبيق (Tiers)","definition":"أربعة مستويات (جزئي، مستنير بالمخاطر، قابل للتكرار، متكيف) لقياس نضج إدارة المخاطر السيبرانية."},{"term":"تحليل الفجوة (Gap Analysis)","definition":"مقارنة الملف الحالي بالملف المستهدف لتحديد الفجوات وصياغة خطة عمل ذات أولويات."}]'::jsonb, '["NIST","CSF","GV.OC","GV.RM","GV.RR","GV.PO","GV.OV","GV.SC","Attack Vectors","Roadmap"]'::jsonb),
  ('cs-s2', 'cybersecurity-governance', 'cs-l2', 'ملخص المحاضرة الثالثة — السياسات وإدارة الحوادث', '2026-08-20', 'published', TRUE, '["السياسة بلا آلية قياس تبقى نصاً غير فعّال.","مراحل الاستجابة: التحضير، الاكتشاف، الاحتواء، الاستئصال، التعافي، الدروس المستفادة.","الاحتواء السريع يقلّل الأثر أكثر من محاولة التحليل الكامل الفوري.","كل حادث فرصة لتحديث الضوابط والسياسات."]'::jsonb, '[{"term":"الحادث السيبراني","definition":"واقعة تمسّ سرية أو سلامة أو توافرية الأصول المعلوماتية."},{"term":"الاحتواء","definition":"إجراءات عزل أثر الحادث ومنع انتشاره."},{"term":"الدروس المستفادة","definition":"مراجعة لاحقة توثّق أسباب الحادث وتحدّث الضوابط."}]'::jsonb, '["خطة الاستجابة","التصعيد","زمن الاكتشاف","زمن التعافي"]'::jsonb),
  ('ip-s1', 'innovation-project-management', 'ip-l1', 'ملخص المحاضرة الأولى — الابتكار', '2026-08-14', 'published', TRUE, '["الاختراع فكرة جديدة، والابتكار فكرة جديدة طُبِّقت وحقّقت قيمة.","الابتكار التدريجي يحسّن القائم، والجذري يغيّر قواعد اللعبة.","الأفكار الكثيرة بلا معايير تصفية تُنتج تشتّتاً لا ابتكاراً.","ثقافة تقبّل الخطأ شرط لبيئة مبتكرة."]'::jsonb, '[{"term":"الابتكار","definition":"تحويل فكرة جديدة إلى منتج أو خدمة أو عملية تحقق قيمة فعلية."},{"term":"الابتكار التدريجي","definition":"تحسينات متتابعة صغيرة على منتج أو عملية قائمة."},{"term":"الابتكار الجذري","definition":"تغيير جوهري يعيد تعريف المنتج أو السوق أو نموذج العمل."}]'::jsonb, '["العصف الذهني","النموذج الأولي","دراسة الجدوى","القيمة المضافة"]'::jsonb),
  ('ip-s2', 'innovation-project-management', 'ip-l2', 'ملخص المحاضرة الثانية — إدارة المشاريع', '2026-08-21', 'published', TRUE, '["مراحل المشروع: البدء، التخطيط، التنفيذ، المراقبة والتحكم، الإغلاق.","القيود الثلاثية: النطاق والزمن والكلفة، وتغيير أحدها يؤثر في الباقي.","زحف النطاق أشيع أسباب تعثّر المشاريع.","المنهج الرشيق أنسب للمشاريع عالية التغيّر، والتقليدي للمشاريع محدّدة المتطلبات."]'::jsonb, '[{"term":"ميثاق المشروع","definition":"وثيقة تعتمد انطلاق المشروع وتحدّد هدفه ونطاقه وأصحاب المصلحة."},{"term":"زحف النطاق","definition":"توسّع غير منضبط في متطلبات المشروع دون تعديل الزمن أو الكلفة."},{"term":"المنهج الرشيق","definition":"تنفيذ تكراري قصير الدورات مع تسليم قيمة مستمرة ومراجعة دورية."}]'::jsonb, '["أصحاب المصلحة","المخرج","المعلم الرئيسي","خط الأساس"]'::jsonb),
  ('ip-s3', 'innovation-project-management', 'ip-l1', 'مفاهيم أساسية', '2026-09-01', 'published', FALSE, '["الابتكار: تحويل فكرة أو معرفة جديدة إلى منتج أو خدمة أو عملية أو نموذج أعمال يخلق قيمة.","الفرق: الإبداع (فكرة) ← الاختراع (تقنية جديدة) ← الابتكار (تطبيق يخلق قيمة) ← ريادة الأعمال (تحويل الفرصة لمشروع).","أنواع الابتكار: منتجات، خدمات، عمليات، تنظيمي، نموذج أعمال، ورقمي.","الاقتصاد الرقمي يعتمد على البيانات والمنصات الرقمية بدل الاعتماد الأساسي على الأصول المادية."]'::jsonb, '[{"term":"الابتكار (Innovation)","definition":"تحويل الفكرة أو الاختراع إلى تطبيق أو منتج أو خدمة يخلق قيمة قابلة للقياس."},{"term":"الاقتصاد الرقمي","definition":"الاقتصاد الذي تعتمد أنشطته بصورة متزايدة على البيانات والتقنيات والبنية التحتية الرقمية."},{"term":"المشروع الرقمي","definition":"مشروع يعتمد بصورة أساسية على التكنولوجيا أو البيانات أو المنصات الرقمية في خلق القيمة."},{"term":"منهجية Agile","definition":"منهجية إدارة مشاريع تعتمد على التطوير المرحلي وفرق صغيرة وسرعة الاستجابة للتغيير."},{"term":"Scrum / Sprints","definition":"تطبيق شهير لمنهجية Agile يعتمد على دورات تطوير قصيرة تُسمى Sprints."},{"term":"Prototype (النموذج الأولي)","definition":"نسخة أولية من المنتج تُستخدم للاختبار قبل التنفيذ الكامل."},{"term":"الابتكار المفتوح (Open Innovation)","definition":"اعتماد المؤسسة على مصادر داخلية وخارجية للمعرفة والأفكار والتكنولوجيا."},{"term":"FinTech (التكنولوجيا المالية)","definition":"تطبيق التكنولوجيا في المدفوعات والتحويلات والتمويل والخدمات المصرفية."}]'::jsonb, '["الابتكار (Innovation)","الاقتصاد الرقمي","المشروع الرقمي","منهجية Agile","Scrum / Sprints","Prototype (النموذج الأولي)","الابتكار المفتوح (Open Innovation)","FinTech (التكنولوجيا المالية)"]'::jsonb),
  ('ip-s4', 'innovation-project-management', 'ip-l1', 'دور الابتكار وإدارة المشاريع الرقمية', '2026-09-01', 'published', FALSE, '["يسهم الابتكار الرقمي في زيادة الإنتاجية، وخلق منتجات وخدمات ووظائف جديدة، وتعزيز التنافسية، ودعم ريادة الأعمال، وتحقيق الشمول المالي.","خصائص المشاريع الرقمية: سرعة التغيّر، عدم اليقين، الاعتماد على البيانات، والحاجة لفرق متعددة التخصصات.","مراحل المشروع الرقمي: تحديد المشكلة ← الفكرة ← دراسة الجدوى ← نموذج أولي ← اختبار ← تنفيذ ← إطلاق ← تقييم وتطوير.","منهجية Agile (وتطبيقها Scrum عبر Sprints) الأنسب للمشاريع الرقمية بسبب سرعة تغيّر التكنولوجيا والسوق."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('ip-s5', 'innovation-project-management', 'ip-l1', 'محركات الابتكار وتحدياته', '2026-09-01', 'published', FALSE, '["أبرز التقنيات المحركة للابتكار: الذكاء الاصطناعي، البيانات الضخمة، الحوسبة السحابية، إنترنت الأشياء، سلسلة الكتل، والتكنولوجيا المالية.","النموذج: فكرة ← ابتكار ← فرصة اقتصادية ← مشروع رقمي ← قيمة اقتصادية ← نمو وتوسع.","الابتكار المفتوح يعتمد على مصادر داخلية وخارجية: الجامعات، الحاضنات، العملاء، المستثمرون.","أبرز التحديات: نقص المهارات، ضعف التمويل والبنية التحتية، المخاطر السيبرانية، وصعوبة الاستدامة المالية."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('ip-s6', 'innovation-project-management', 'ip-l1', 'الابتكار في العراق والاستدامة', '2026-09-01', 'published', FALSE, '["قطاعات عراقية واعدة للابتكار الرقمي: المصرفي، التعليم، الصناعة، الزراعة، وإدارة الموارد المائية والحكومة.","نموذج تحليل متكامل لأي مشروع رقمي: المشكلة ← الفكرة ← الابتكار ← التكنولوجيا ← نموذج الأعمال ← المشروع ← السوق ← القيمة ← الاستدامة.","المعادلة الأساسية: الابتكار + التكنولوجيا الرقمية + ريادة الأعمال + إدارة المشاريع = خلق القيمة في الاقتصاد الرقمي.","الابتكار أداة للاستدامة الاقتصادية والاجتماعية، لا لزيادة الأرباح فقط."]'::jsonb, '[]'::jsonb, '[]'::jsonb),
  ('ip-s7', 'innovation-project-management', 'ip-l3', 'نظريات ونماذج الابتكار الحديثة', '2026-09-02', 'published', FALSE, '["الابتكار التدريجي: تحسينات صغيرة ومستمرة، مخاطر منخفضة، موجّه للعملاء والأسواق الحالية.","الابتكار الجذري: تغيير ثوري يخلق أسواقاً جديدة (التدمير الخلّاق لشومبيتر)، مخاطر مرتفعة جداً، يحتاج وحدات تنظيمية مستقلة (منظمات استضمارية).","الابتكار المفتوح (تشيسبرو): الاعتماد على مصادر داخلية وخارجية للمعرفة، بثلاثة اتجاهات: من الخارج للداخل، من الداخل للخارج، والمتقاطع.","نموذج الابتكار المستمر: دمج الابتكار في الثقافة اليومية لكل العاملين، مستمد من Kaizen والرشاقة المؤسسية والإدارة الهزيلة.","النماذج الثلاثة تتكامل: التدريجي والمستمر للكفاءة التشغيلية القصيرة الأجل، والجذري لبقاء طويل الأجل، والمفتوح لتسريع كليهما."]'::jsonb, '[{"term":"الابتكار الجذري (Radical Innovation)","definition":"تغيير ثوري وهدّام يخلق أسواقاً جديدة كلياً أو يزيح المنتجات والتقنيات القائمة."},{"term":"التدمير الخلّاق (Creative Destruction)","definition":"مفهوم شومبيتري يصف كيف يزيح الابتكار الجذري المنتجات والتقنيات القائمة بالكامل."},{"term":"الابتكار المفتوح (Open Innovation)","definition":"نموذج هنري تشيسبرو القائم على الانفتاح على البيئة الخارجية للاستفادة من الأفكار والتقنيات والخبرات."},{"term":"نموذج الابتكار المستمر","definition":"نهج إداري يدمج الابتكار في صلب الثقافة اليومية والعمليات التشغيلية بمشاركة كل العاملين."}]'::jsonb, '["الابتكار التدريجي","الابتكار الجذري","التدمير الخلّاق","المنظمات الاستضمارية","الابتكار المفتوح","Inbound / Outbound / Coupled Open Innovation","Kaizen","الرشاقة المؤسسية"]'::jsonb),
  ('rm-s1', 'risk-management', 'rm-l1', 'ملخص المحاضرة الأولى — لماذا لا تكفي معرفة الخطر؟', '2026-09-09', 'published', FALSE, '["مقارنة محطتَي فوكوشيما وأوناغاوا: المعرفة بالخطر كانت موجودة في الحالتين، لكن الفارق في النتيجة صنعه القرار لا مجرد المعرفة.","الخطر ليس حدثاً واحداً، بل نتيجة تفاعل ثلاثة عناصر: المُخطِر (خارج سلطة المدير)، والتعرّض، وقابلية التأثر (ضمن نطاق القرار).","تعريف ISO 31000: الخطر هو «أثر عدم اليقين في الأهداف» — لا خطر بلا هدف، والخطر نسبي بين المؤسسات.","إدارة المخاطر تختلف عن الرقابة الداخلية والتدقيق الداخلي والامتثال — لكل منها سؤالها الخاص.","المخاطرة (نايت) تختلف عن عدم اليقين وعن الغموض (إلسبرغ)؛ و«وهم السيطرة» يدفع الخبراء لمعاملة المواقف الغامضة كأنها مخاطر قابلة للحساب.","التهوّر والجمود والمخاطرة المحسوبة ثلاثة أوضاع مختلفة؛ الفرق بينها في جودة عملية القرار لا في النتيجة.","اختبار الأثر القراري: كم قراراً تغيّر فعلياً بسبب تحليل المخاطر؟ — المعيار الحقيقي لفاعلية المنظومة."]'::jsonb, '[{"term":"المُخطِر (Hazard)","definition":"الظاهرة نفسها المصدر للضرر المحتمل، خارج سلطة أي مدير."},{"term":"التعرّض (Exposure)","definition":"وجود أصول أو خدمات أو أشخاص في مرمى الظاهرة — قرار يقع ضمن نطاق الإدارة."},{"term":"قابلية التأثر (Vulnerability)","definition":"الخصائص التي تجعل الأصل أكثر عرضة للانهيار أو أكثر قدرة على الصمود."},{"term":"شهية المخاطر (Risk Appetite)","definition":"طبيعة ومدى المخاطر التي تكون المؤسسة مستعدة لأخذها لتحقيق أهدافها."},{"term":"اختبار الأثر القراري","definition":"قياس عدد القرارات الفعلية التي تغيّرت بسبب تحليل المخاطر، بدلاً من الاكتفاء باكتمال سجل المخاطر."}]'::jsonb, '["حلقة الخطر–القرار","المخاطرة والغموض وعدم اليقين","وهم السيطرة","التهوّر والجمود","ISO 31000","COSO"]'::jsonb),
  ('rm-s2', 'risk-management', 'rm-l2', 'ملخص المحاضرة الثانية — التقييم والمعالجة', '2026-08-22', 'published', TRUE, '["مصفوفة المخاطر تُرتّب المخاطر حسب الاحتمال والأثر لتحديد الأولوية.","استراتيجيات المعالجة أربع: التجنّب، التقليل، النقل، القبول.","كل خطر يحتاج مالكاً محدّداً وتاريخ مراجعة.","المخاطر المتبقية بعد المعالجة يجب أن تكون ضمن شهية المخاطر."]'::jsonb, '[{"term":"التجنّب","definition":"تغيير الخطة لإزالة مصدر الخطر تماماً."},{"term":"التقليل","definition":"إجراءات تخفّض احتمال وقوع الخطر أو أثره."},{"term":"النقل","definition":"تحويل أثر الخطر لطرف آخر كالتأمين أو التعاقد."},{"term":"القبول","definition":"تحمّل الخطر عن وعي عندما تكون كلفة المعالجة أعلى من أثره."}]'::jsonb, '["سجل المخاطر","مصفوفة المخاطر","مؤشر الإنذار المبكر","خطة الطوارئ"]'::jsonb)
insert into assignments (id, subject_id, title, difficulty, date, due, status, demo, description) values
  ('ai-a1', 'ai-data', 'تعليماتك الشخصية الدائمة', 'easy', '2026-09-01', NULL, 'published', FALSE, 'اكتب نصًا لا يتجاوز خمسة أسطر يعرّف بك: موقعك الوظيفي، وطبيعة عملك، وأسلوب الرد الذي تفضّله. ضعه في الإعدادات، ثم اطرح السؤال نفسه قبل إضافته وبعدها وقارن الفرق.
insert into quizzes (id, subject_id, title, status, demo, description) values
  ('ai-q1', 'ai-data', 'اختبار المادة — الذكاء الاصطناعي وتحليل البيانات', 'published', FALSE, 'أسئلة تفاعلية بالأنواع الستة: اختيار من متعدد، صح وخطأ، وأسئلة سيناريو ومقالية للتقييم الذاتي.'),
  ('lg-q1', 'legal-regulatory', 'اختبار المادة — الثقافة القانونية والتنظيمية', 'published', FALSE, 'أسئلة تفاعلية تغطي الإطار القانوني والامتثال وحماية البيانات.'),
  ('cs-q1', 'cybersecurity-governance', 'اختبار المادة — حوكمة الأمن السيبراني', 'published', FALSE, 'أسئلة تفاعلية حول مفاهيم الأمن السيبراني، مثلث CIA، أركان الحوكمة السيبرانية وإدارة الحوادث.'),
  ('ip-q1', 'innovation-project-management', 'اختبار المادة — الابتكار وإدارة المشاريع', 'published', FALSE, 'أسئلة تفاعلية حول الابتكار ودورة حياة المشروع والقيود الثلاثية.'),
  ('rm-q1', 'risk-management', 'اختبار المادة — إدارة المخاطر', 'published', FALSE, 'أسئلة تفاعلية حول مفهوم الخطر وتقييمه واستراتيجيات معالجته.')
insert into questions (id, quiz_id, lecture_id, type, difficulty, prompt, kind, explanation, answer, rubric, status) values
  ('ai-q1-1', 'ai-q1', 'ai-l1', 'mcq', 'medium', 'النموذج اللغوي الكبير (LLM) يعمل بشكل أساسي عن طريق:', NULL, 'النموذج لا يفهم ولا يبحث لحظيًا؛ هو يتوقّع الكلمة الأنسب التالية اعتمادًا على أنماط إحصائية تعلّمها من نصوص التدريب، لذلك تكون مخرجاته مقنعة الصياغة حتى حين تكون خاطئة المضمون.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-2', 'ai-q1', 'ai-l1', 'mcq', 'medium', '«الهلوسة» (Hallucination) في الذكاء الاصطناعي تعني:', NULL, 'الهلوسة خطأ في المضمون لا في الشكل: معلومة مختلَقة تُقدَّم بلغة واثقة، والعلاج التحقق من كل معلومة حساسة من مصدر موثوق قبل اعتمادها.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-3', 'ai-q1', 'ai-l2', 'mcq', 'medium', 'أي أداة من أدوات كلود الأنسب لتنظيم ملفاتك وجدولة مهام تتكرر يوميًا تلقائيًا؟', NULL, 'كوورك واجهة المهام الكبيرة: وصول حقيقي للملفات، عمل بالخلفية، وجدولة تلقائية؛ الشات للمهام السريعة، والكود للعمل البرمجي.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-4', 'ai-q1', 'ai-l1', 'mcq', 'medium', 'حسب «القواعد الذهبية الأربع» لكتابة أمر ناجح، أول خطوة هي:', NULL, 'الترتيب: الموقف والسياق ← المهمة بوضوح ← القواعد والشكل ← تقديم مثال. السياق أولًا لأنه يحدّد من أنت ولمن تكتب.', '2'::jsonb, NULL, 'published'),
  ('ai-q1-5', 'ai-q1', 'ai-l1', 'mcq', 'medium', 'أي نموذج من نماذج كلود هو «الافتراضي» المتوازن لمعظم المهام اليومية؟', NULL, 'هايكو للسرعة، وأوبس للدقة العالية في المهام المعقدة، وسونيت هو التوازن بينهما والخيار الافتراضي لأغلب الأعمال اليومية.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-6', 'ai-q1', 'ai-l2', 'mcq', 'medium', 'مهمة في Cowork حالتها «تحتاج ردك» (Needs input) تعني:', NULL, 'هذه الحالة تعني أن كلود وصل إلى نقطة تحتاج قرارًا بشريًا — أول ما تراجعه في يومك لأنها تعطّل بقية سلسلة العمل.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-7', 'ai-q1', 'ai-l2', 'mcq', 'medium', 'إعداد «طلب أجهزة موثوقة» (Require trusted devices) وظيفته:', NULL, 'إعداد أمني بالدرجة الأولى يمنع أي جهاز غير معتمد من بدء جلسة تصل إلى ملفاتك — يُبقى مفعّلًا دائمًا في بيئة العمل الرسمي.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-8', 'ai-q1', 'ai-l2', 'mcq', 'medium', 'رابط تصدير البيانات (Export data) يصلك:', NULL, 'التصدير يصلك رابط تنزيل على البريد بصلاحية ٢٤ ساعة فقط، لأن الأرشيف يحوي محادثاتك ومشاريعك كاملة.', '0'::jsonb, NULL, 'published'),
  ('ai-q1-9', 'ai-q1', 'ai-l2', 'mcq', 'medium', 'أي خيار في «المهارات» هو الأنسب لموظف مبتدئ يريد بناء مهارة أول مرة؟', NULL, 'Create with Claude يبني المهارة بالحوار: تصفها بالكلام فيسألك أسئلة قليلة ثم يولّدها؛ أما Create a skill فيتطلب كتابتها من الصفر.', '2'::jsonb, NULL, 'published'),
  ('ai-q1-10', 'ai-q1', 'ai-l2', 'mcq', 'medium', '«إعادة الشحن التلقائي» (Auto-reload) في الفوترة تعني:', NULL, 'ميزة تمنع توقف العمل عند نفاد الرصيد، لكنها تصرف مالًا بلا استئذان في كل مرة، لذلك تُفعَّل بوعي بالكلفة وسقف معلوم.', '1'::jsonb, NULL, 'published'),
  ('ai-q1-11', 'ai-q1', 'ai-l1', 'tf', 'medium', 'النموذج اللغوي الكبير «يفكّر» بنفس طريقة تفكير الإنسان.', NULL, 'هو يتوقّع الكلمة التالية إحصائيًا؛ التشابه في الشكل اللغوي لا يعني تشابهًا في آلية التفكير.', 'false'::jsonb, NULL, 'published'),
  ('ai-q1-12', 'ai-q1', 'ai-l1', 'tf', 'medium', 'يجب دائمًا التحقق من المعلومات الحساسة التي يقدّمها الذكاء الاصطناعي من مصدر موثوق.', NULL, 'هذه القاعدة الأولى في التعامل الآمن مع الأداة، وهي الحاجز الوحيد أمام أثر الهلوسة.', 'true'::jsonb, NULL, 'published'),
  ('ai-q1-13', 'ai-q1', 'ai-l1', 'tf', 'medium', '«التفكير الممتد» يُفضَّل تفعيله لكل سؤال لأنه لا يُكلّف شيئًا إضافيًا.', NULL, 'التفكير الممتد يستهلك وقتًا ورصيدًا أكبر، فيُستعمل للمهام المعقدة التي تستحقّه لا لكل سؤال.', 'false'::jsonb, NULL, 'published'),
  ('ai-q1-14', 'ai-q1', 'ai-l1', 'tf', 'medium', 'نافذة السياق الكبيرة تعني أن كلود يتذكّر كل شيء للأبد حتى بعد إغلاق المحادثة.', NULL, 'نافذة السياق تخصّ المحادثة الواحدة ولها حدّ؛ الاستمرارية عبر الجلسات تأتي من المشاريع والتعليمات الدائمة لا من النافذة.', 'false'::jsonb, NULL, 'published'),
  ('ai-q1-15', 'ai-q1', 'ai-l2', 'tf', 'medium', 'الإرسال إلى وكلاء فرعيين (Dispatch) يساعد على إبقاء المحادثة الأساسية مركّزة.', NULL, 'الوكيل الفرعي ينفّذ البحث والاستكشاف بعيدًا ويعيد النتيجة النهائية فقط، فلا تتضخّم المحادثة الأساسية بالتفاصيل.', 'true'::jsonb, NULL, 'published'),
  ('ai-q1-16', 'ai-q1', 'ai-l2', 'tf', 'medium', '«ديسباتش» و«كوورك» واجهتان مستقلتان في الشريط الجانبي.', NULL, 'كل منهما مدخل قائم بذاته: كوورك للمهام الكبيرة على ملفاتك، وديسباتش لإرسال مهمة تُنفَّذ بعيدًا وتعود بنتيجتها.', 'true'::jsonb, NULL, 'published'),
  ('ai-q1-17', 'ai-q1', 'ai-l2', 'tf', 'medium', 'المهمة المؤرشفة تُحذف نهائيًا ولا يمكن استرجاعها.', NULL, 'الأرشفة إخفاء من القائمة النشطة فقط، والمهمة تبقى قابلة للرجوع إليها؛ الحذف إجراء آخر مختلف.', 'false'::jsonb, NULL, 'published'),
  ('ai-q1-18', 'ai-q1', 'ai-l2', 'tf', 'medium', 'تصنيف حالة الجلسة تلقائيًا يُحسب من رصيد استخدام خطتك.', NULL, 'التصنيف التلقائي عملية يقوم بها النموذج ولها كلفة تُحتسب من رصيدك، لذلك يمكن إطفاؤه إن لم تكن بحاجته.', 'true'::jsonb, NULL, 'published'),
  ('ai-q1-19', 'ai-q1', 'ai-l2', 'tf', 'medium', 'مراجعة الجلسات النشطة إجراء أمني ينبغي تكراره دوريًا.', NULL, 'أي جهاز أو موقع لا تعرفه في القائمة يعني حسابًا مفتوحًا في مكان لا تريده، وكشفه المبكر يقلّل الضرر.', 'true'::jsonb, NULL, 'published'),
  ('ai-q1-20', 'ai-q1', 'ai-l2', 'tf', 'medium', 'تفعيل إعدادات الخصوصية يبيح رفع البيانات السرّية للدائرة.', NULL, 'الإعدادات تقلّل مخاطر الاستخدام اللاحق للبيانات، لكنها لا تغيّر تصنيف البيانات نفسه؛ ما هو سرّي لا يُرفع أصلًا.', 'false'::jsonb, NULL, 'published'),
  ('ai-q1-21', 'ai-q1', 'ai-l1', 'open', 'hard', 'موظف بدائرتك كتب لكلود: «اكتب لي كتابًا رسميًا» بدون أي تفاصيل أخرى، وحصل على نتيجة عامة لا تناسب طبيعة عمله. ما الخطأ هنا، وكيف يصححه؟', 'سيناريو', 'تشخيص الخطأ: أمر عام يفتقر إلى السياق والمعطيات، فأنتج نصًا عامًا بالضرورة. القاعدة الأولى — الموقف والسياق: يحدّد موقعه الوظيفي واسم الدائرة والجهة المُرسَل إليها. القاعدة الثانية — المهمة بوضوح: يعطي المعطيات الفعلية (رقم المعاملة، السبب، الموعد الجديد). القاعدة الثالثة — القواعد والشكل: كتاب رسمي بثلاث فقرات، بلا عبارات مبالغة، وبطول محدّد. القاعدة الرابعة — تقديم مثال: يرفق نموذج كتاب سابق معتمد ليقلّد أسلوبه. تثبيت الأسلوب مستقبلًا في التعليمات الدائمة أو داخل مشروع، ومراجعة النص قبل التوقيع.', NULL, '[{"text":"تشخيص الخطأ: أمر عام يفتقر إلى السياق والمعطيات، فأنتج نصًا عامًا بالضرورة.","keywords":["غموض","السياق","عام","تفاصيل","معطيات","ناقص"]},{"text":"القاعدة الأولى — الموقف والسياق: يحدّد موقعه الوظيفي واسم الدائرة والجهة المُرسَل إليها.","keywords":["الموقف","السياق","الدائرة","الوظيفي","الجهة"]},{"text":"القاعدة الثانية — المهمة بوضوح: يعطي المعطيات الفعلية (رقم المعاملة، السبب، الموعد الجديد).","keywords":["المهمة","المعاملة","السبب","الموعد","المعطيات","الرقم"]},{"text":"القاعدة الثالثة — القواعد والشكل: كتاب رسمي بثلاث فقرات، بلا عبارات مبالغة، وبطول محدّد.","keywords":["الشكل","فقرات","رسمي","القواعد","مبالغة","الطول","التنسيق"]},{"text":"القاعدة الرابعة — تقديم مثال: يرفق نموذج كتاب سابق معتمد ليقلّد أسلوبه.","keywords":["مثال","نموذج","سابق","يرفق"]},{"text":"تثبيت الأسلوب مستقبلًا في التعليمات الدائمة أو داخل مشروع، ومراجعة النص قبل التوقيع.","keywords":["التعليمات الدائمة","مشروع","المراجعة","التوقيع"]}]'::jsonb, 'published'),
  ('ai-q1-22', 'ai-q1', 'ai-l1', 'open', 'hard', 'مدير يستخدم كلود لتلخيص تقرير طويل، وبعد ٤٠ دقيقة لاحظ أن الإجابات بدأت تفقد دقتها وتتجاهل تفاصيل ذكرها بالبداية. ما تفسير هذا، وما الإجراء المناسب؟', 'سيناريو', 'التفسير: نافذة السياق محدودة، وفي المحادثات الطويلة يفقد النموذج تدريجيًا تفاصيل بدايتها. إعادة تثبيت المعطيات: تلخيص النقاط والقرارات المهمة في رسالة جديدة داخل المحادثة. بدء محادثة جديدة أو مشروع يحمل الخلاصة والملفات المرجعية بدل الاستمرار في محادثة متضخّمة. تقسيم التقرير إلى أجزاء ومعالجة كل جزء على حدة ثم دمج الملخّصات. التحقق من التفاصيل الحساسة بمطابقتها بالتقرير الأصلي قبل الاعتماد.', NULL, '[{"text":"التفسير: نافذة السياق محدودة، وفي المحادثات الطويلة يفقد النموذج تدريجيًا تفاصيل بدايتها.","keywords":["نافذة","السياق","محدود","يفقد","البداية","طويلة"]},{"text":"إعادة تثبيت المعطيات: تلخيص النقاط والقرارات المهمة في رسالة جديدة داخل المحادثة.","keywords":["تلخيص","تثبيت","إعادة","النقاط","تذكير"]},{"text":"بدء محادثة جديدة أو مشروع يحمل الخلاصة والملفات المرجعية بدل الاستمرار في محادثة متضخّمة.","keywords":["محادثة جديدة","مشروع","ملف"]},{"text":"تقسيم التقرير إلى أجزاء ومعالجة كل جزء على حدة ثم دمج الملخّصات.","keywords":["تقسيم","أجزاء","جزء","مراحل"]},{"text":"التحقق من التفاصيل الحساسة بمطابقتها بالتقرير الأصلي قبل الاعتماد.","keywords":["التحقق","الأصلي","مطابقة","الاعتماد"]}]'::jsonb, 'published'),
  ('ai-q1-23', 'ai-q1', 'ai-l1', 'open', 'hard', 'موظف اعتمد على رقم مالي أعطاه كلود دون التحقق منه، وتبيّن لاحقًا أنه غير دقيق. أي مبادئ المحاضرة كان يجب اتّباعه؟', 'سيناريو', 'مبدأ افتراض الهلوسة: الإجابة قد تكون خاطئة بثقة حتى يثبت العكس. التحقق من كل معلومة حساسة — والأرقام المالية في مقدّمتها — من مصدر موثوق. مطابقة الرقم بالسجل أو المستند الرسمي قبل إدراجه في أي مخرج. الإشراف البشري: المسؤولية تقع على الموظف الموقّع لا على الأداة. عمليًا: رفع الملف المصدري وطلب الاستخراج منه بدل الاعتماد على ذاكرة النموذج.', NULL, '[{"text":"مبدأ افتراض الهلوسة: الإجابة قد تكون خاطئة بثقة حتى يثبت العكس.","keywords":["الهلوسة","خاطئة","بثقة","افتراض"]},{"text":"التحقق من كل معلومة حساسة — والأرقام المالية في مقدّمتها — من مصدر موثوق.","keywords":["التحقق","حساسة","مصدر","موثوق","الأرقام"]},{"text":"مطابقة الرقم بالسجل أو المستند الرسمي قبل إدراجه في أي مخرج.","keywords":["مطابقة","السجل","المستند","الرسمي"]},{"text":"الإشراف البشري: المسؤولية تقع على الموظف الموقّع لا على الأداة.","keywords":["الإشراف","البشري","المسؤولية","التوقيع","الموظف"]},{"text":"عمليًا: رفع الملف المصدري وطلب الاستخراج منه بدل الاعتماد على ذاكرة النموذج.","keywords":["رفع الملف","المصدر","استخراج","ذاكرة"]}]'::jsonb, 'published'),
  ('ai-q1-24', 'ai-q1', 'ai-l2', 'open', 'hard', 'موظف يفتح ملف الردود كل صباح، يفحصه يدويًا، ويكتب ملخّصًا — عشر دقائق يوميًا تضيع. أي واجهة تحلّ له هذا، وكيف يُعدّها؟', 'سيناريو', 'الحل: المهام المجدولة (Scheduled runs) من كوورك. صياغة الطلب: مراجعة الملف كل صباح في ساعة محدّدة وإرسال ملخّص. إنشاء المشغّل (Trigger) الذي يطلق المهمة، وتحديد مصدر الملف ووجهة المخرج. متابعة سجل التنفيذات للتأكد من أن المهمة تعمل ولم تفوّت يومًا. الأثر: تحوّل الدور من التنفيذ اليدوي إلى المراجعة والقرار، وتوفير الوقت.', NULL, '[{"text":"الحل: المهام المجدولة (Scheduled runs) من كوورك.","keywords":["مجدول","scheduled","كوورك","الجدولة"]},{"text":"صياغة الطلب: مراجعة الملف كل صباح في ساعة محدّدة وإرسال ملخّص.","keywords":["صباح","الساعة","يومي","محدد","وقت"]},{"text":"إنشاء المشغّل (Trigger) الذي يطلق المهمة، وتحديد مصدر الملف ووجهة المخرج.","keywords":["المشغل","trigger","الملف","المخرج"]},{"text":"متابعة سجل التنفيذات للتأكد من أن المهمة تعمل ولم تفوّت يومًا.","keywords":["سجل","التنفيذات","متابعة","تفويت"]},{"text":"الأثر: تحوّل الدور من التنفيذ اليدوي إلى المراجعة والقرار، وتوفير الوقت.","keywords":["مراجعة","قرار","توفير","الوقت","الأثر"]}]'::jsonb, 'published'),
  ('ai-q1-25', 'ai-q1', 'ai-l2', 'open', 'hard', 'مديرة فتحت «الجلسات النشطة» فوجدت جهازًا وموقعًا لا تعرفهما. ما دلالة ذلك، وما الإجراءات الواجبة فورًا؟', 'سيناريو', 'الدلالة: حسابها مفتوح على جهاز غير مصرَّح به — احتمال وصول غير مشروع. إنهاء تلك الجلسة فورًا من قائمة الجلسات النشطة. تغيير كلمة المرور وتفعيل التحقق بخطوتين. مراجعة الأجهزة الموثوقة وحذف غير المعروف منها، وتفعيل «طلب أجهزة موثوقة». إبلاغ مسؤول أمن المعلومات في الدائرة ومراجعة ما قد يكون اطُّلع عليه من محادثات وملفات. جعل مراجعة الجلسات النشطة إجراءً أمنيًا دوريًا لا ردّ فعل.', NULL, '[{"text":"الدلالة: حسابها مفتوح على جهاز غير مصرَّح به — احتمال وصول غير مشروع.","keywords":["اختراق","غير مصرح","مفتوح","وصول"]},{"text":"إنهاء تلك الجلسة فورًا من قائمة الجلسات النشطة.","keywords":["إنهاء","إغلاق","فورا","الجلسة","تسجيل الخروج"]},{"text":"تغيير كلمة المرور وتفعيل التحقق بخطوتين.","keywords":["كلمة المرور","تغيير","التحقق","خطوتين"]},{"text":"مراجعة الأجهزة الموثوقة وحذف غير المعروف منها، وتفعيل «طلب أجهزة موثوقة».","keywords":["الأجهزة الموثوقة","حذف","موثوق"]},{"text":"إبلاغ مسؤول أمن المعلومات في الدائرة ومراجعة ما قد يكون اطُّلع عليه من محادثات وملفات.","keywords":["إبلاغ","أمن","مسؤول","مراجعة المحادثات"]},{"text":"جعل مراجعة الجلسات النشطة إجراءً أمنيًا دوريًا لا ردّ فعل.","keywords":["دوري","إجراء","روتين"]}]'::jsonb, 'published'),
  ('ai-q1-26', 'ai-q1', 'ai-l2', 'open', 'hard', 'موظف يريد أن تبقى مهامه على حاسوب الدائرة ولا تكمل في السحابة بعد إغلاق الجهاز. أي إعداد يستخدم، وما الأثر المترتب عليه؟', 'سيناريو', 'الإعداد: كوورك ← تفعيل «على حاسوبك فقط» (Only on your computer). الأثر المباشر: المهام تبقى على الجهاز وتتوقف عند إغلاقه ولا تكمل في السحابة. المقابل: فقدان ميزة العمل بالخلفية وإكمال المهام الطويلة أثناء إغلاق الجهاز. الملاءمة: مناسب للبيانات الحساسة وسياسات الدوائر التي تمنع المعالجة السحابية. يُستحسن اقترانه بتفعيل «طلب أجهزة موثوقة» لضبط أي جهاز يبدأ الجلسة.', NULL, '[{"text":"الإعداد: كوورك ← تفعيل «على حاسوبك فقط» (Only on your computer).","keywords":["only","حاسوبك","كوورك","المحلي"]},{"text":"الأثر المباشر: المهام تبقى على الجهاز وتتوقف عند إغلاقه ولا تكمل في السحابة.","keywords":["تتوقف","إغلاق","السحابة","تكمل"]},{"text":"المقابل: فقدان ميزة العمل بالخلفية وإكمال المهام الطويلة أثناء إغلاق الجهاز.","keywords":["خلفية","الطويلة","ميزة","تفوت"]},{"text":"الملاءمة: مناسب للبيانات الحساسة وسياسات الدوائر التي تمنع المعالجة السحابية.","keywords":["حساسة","سرية","سياسة","أمان"]},{"text":"يُستحسن اقترانه بتفعيل «طلب أجهزة موثوقة» لضبط أي جهاز يبدأ الجلسة.","keywords":["موثوقة","require","أجهزة"]}]'::jsonb, 'published'),
  ('ai-q1-27', 'ai-q1', 'ai-l1', 'open', 'hard', 'اشرح بأسلوبك الخاص الفرق بين «عقلية اللقطة الواحدة» و«عقلية التكرار»، ومثّل لكل منهما بموقف من عملك اليومي.', 'مقالي', 'اللقطة الواحدة: توقّع إجابة كاملة من أمر واحد، فإما تُقبل كما هي أو تُرفض كلّها. عقلية التكرار: بناء السياق تدريجيًا وتقديم ملاحظات محدّدة بعد كل نتيجة لتحسينها. معيار الاختيار: اللقطة الواحدة تكفي للمهام البسيطة والمعروفة، والتكرار ضروري للمهام المعقدة أو ذات الأسلوب الخاص. مثال للقطة الواحدة من العمل: صياغة رسالة قصيرة أو تصحيح لغوي. مثال للتكرار من العمل: إعداد تقرير أو دراسة تُبنى على مراحل مع مراجعة كل مرحلة. الأثر: التكرار يرفع جودة الناتج ويقلّل زمن المراجعة النهائية رغم أنه يبدو أطول.', NULL, '[{"text":"اللقطة الواحدة: توقّع إجابة كاملة من أمر واحد، فإما تُقبل كما هي أو تُرفض كلّها.","keywords":["لقطة","مرة واحدة","امر واحد","دفعة"]},{"text":"عقلية التكرار: بناء السياق تدريجيًا وتقديم ملاحظات محدّدة بعد كل نتيجة لتحسينها.","keywords":["التكرار","تدريجي","ملاحظات","تصحيح","تحسين"]},{"text":"معيار الاختيار: اللقطة الواحدة تكفي للمهام البسيطة والمعروفة، والتكرار ضروري للمهام المعقدة أو ذات الأسلوب الخاص.","keywords":["بسيطة","معقدة","سريعة","معيار"]},{"text":"مثال للقطة الواحدة من العمل: صياغة رسالة قصيرة أو تصحيح لغوي.","keywords":["رسالة","قصيرة","تصحيح"]},{"text":"مثال للتكرار من العمل: إعداد تقرير أو دراسة تُبنى على مراحل مع مراجعة كل مرحلة.","keywords":["تقرير","دراسة","مسودة","مراحل"]},{"text":"الأثر: التكرار يرفع جودة الناتج ويقلّل زمن المراجعة النهائية رغم أنه يبدو أطول.","keywords":["جودة","الوقت","المراجعة","نتيجة افضل"]}]'::jsonb, 'published'),
  ('ai-q1-28', 'ai-q1', 'ai-l2', 'open', 'hard', 'ناقش كيف يمكن الاستفادة من «المشاريع» (Projects) بتنظيم عمل دائرة حكومية تتعامل مع نفس نوع المعاملات بشكل متكرر.', 'مقالي', 'إنشاء مشروع مستقل لكل نوع معاملة، بتعليمات ثابتة تصف الأسلوب والشكل المطلوب. رفع الملفات المرجعية: النماذج المعتمدة والتعاميم والقوانين لتكون قاعدة معرفة المشروع. توحيد الصياغة بين الموظفين وتقليل التباين في المخرجات الرسمية. اختصار الزمن: لا حاجة لإعادة شرح السياق في كل معاملة جديدة. استمرارية المعرفة المؤسسية عند تغيّر الموظفين، لأن الأسلوب مخزون في المشروع لا في ذاكرة شخص. الضوابط: تصنيف البيانات وعدم رفع السرّي، ومراجعة بشرية قبل اعتماد أي مخرج.', NULL, '[{"text":"إنشاء مشروع مستقل لكل نوع معاملة، بتعليمات ثابتة تصف الأسلوب والشكل المطلوب.","keywords":["مشروع","تعليمات","ثابتة","مستقل"]},{"text":"رفع الملفات المرجعية: النماذج المعتمدة والتعاميم والقوانين لتكون قاعدة معرفة المشروع.","keywords":["ملفات","مرجعية","نماذج","تعاميم","قاعدة المعرفة"]},{"text":"توحيد الصياغة بين الموظفين وتقليل التباين في المخرجات الرسمية.","keywords":["توحيد","الصياغة","تباين","موحد"]},{"text":"اختصار الزمن: لا حاجة لإعادة شرح السياق في كل معاملة جديدة.","keywords":["الوقت","الزمن","إعادة شرح","اختصار"]},{"text":"استمرارية المعرفة المؤسسية عند تغيّر الموظفين، لأن الأسلوب مخزون في المشروع لا في ذاكرة شخص.","keywords":["استمرارية","المؤسسية","تغير الموظف","تسليم"]},{"text":"الضوابط: تصنيف البيانات وعدم رفع السرّي، ومراجعة بشرية قبل اعتماد أي مخرج.","keywords":["سري","تصنيف","مراجعة","بشري","الخصوصية"]}]'::jsonb, 'published'),
  ('ai-q1-29', 'ai-q1', 'ai-l2', 'open', 'hard', 'ناقش الإعدادات التي يجب على دائرة حكومية ضبطها قبل السماح لموظفيها باستخدام كلود في العمل الرسمي، ولماذا كل واحد منها.', 'مقالي', 'الملف الشخصي والتعليمات الدائمة الموحّدة لضمان أسلوب رسمي ثابت لكل الموظفين. «طلب أجهزة موثوقة» ومراجعة الجلسات النشطة دوريًا لمنع الوصول غير المصرَّح. الخصوصية: ضبط التصدير والحذف، وإلزام إخفاء الهوية وتصنيف البيانات قبل الرفع. القدرات والموصلات: تفعيل ما تحتاجه الدائرة فقط، وربط حسابات عمل رسمية لا شخصية. الفوترة والاستخدام: ضبط إعادة الشحن التلقائي ومراقبة الاستهلاك ضمن سقف معلوم. خيار «على حاسوبك فقط» للمهام التي تمسّ بيانات لا يجوز خروجها إلى السحابة. الحوكمة: سياسة استخدام مؤسسي تحدّد من يستخدم ولأي غرض وبأي صلاحية، مع إشراف بشري قبل الاعتماد.', NULL, '[{"text":"الملف الشخصي والتعليمات الدائمة الموحّدة لضمان أسلوب رسمي ثابت لكل الموظفين.","keywords":["التعليمات","الملف الشخصي","موحد","أسلوب"]},{"text":"«طلب أجهزة موثوقة» ومراجعة الجلسات النشطة دوريًا لمنع الوصول غير المصرَّح.","keywords":["الأجهزة الموثوقة","الجلسات النشطة","مراجعة","وصول"]},{"text":"الخصوصية: ضبط التصدير والحذف، وإلزام إخفاء الهوية وتصنيف البيانات قبل الرفع.","keywords":["الخصوصية","تصدير","حذف","إخفاء الهوية","تصنيف"]},{"text":"القدرات والموصلات: تفعيل ما تحتاجه الدائرة فقط، وربط حسابات عمل رسمية لا شخصية.","keywords":["القدرات","الموصلات","ربط","حساب"]},{"text":"الفوترة والاستخدام: ضبط إعادة الشحن التلقائي ومراقبة الاستهلاك ضمن سقف معلوم.","keywords":["الفوترة","إعادة الشحن","رصيد","استهلاك"]},{"text":"خيار «على حاسوبك فقط» للمهام التي تمسّ بيانات لا يجوز خروجها إلى السحابة.","keywords":["حاسوبك","السحابة","محلي","only"]},{"text":"الحوكمة: سياسة استخدام مؤسسي تحدّد من يستخدم ولأي غرض وبأي صلاحية، مع إشراف بشري قبل الاعتماد.","keywords":["سياسة","حوكمة","إشراف","صلاحية","اعتماد"]}]'::jsonb, 'published'),
  ('lg-q1-1', 'lg-q1', 'lg-l3', 'mcq', 'easy', 'أي مما يلي يعبّر عن مبدأ تدرّج القواعد القانونية؟', NULL, 'التدرّج يعني أن الأدنى مرتبةً (اللائحة/التعليمات) لا يجوز أن يخالف الأعلى (الدستور/القانون).', '1'::jsonb, NULL, 'published'),
  ('lg-q1-2', 'lg-q1', 'lg-l2', 'tf', 'easy', 'الامتثال التنظيمي إجراء يُنفَّذ مرة واحدة عند تأسيس الجهة.', NULL, 'الامتثال التزام مستمر يتطلب متابعة دورية وتحديثاً كلما تغيّرت التشريعات أو الأنشطة.', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-3', 'lg-q1', 'lg-l2', 'fill', 'medium', 'المبدأ الذي يقضي بجمع أقل قدر ممكن من البيانات لتحقيق الغرض يسمّى مبدأ ............ البيانات.', NULL, 'مبدأ تقليل البيانات (Data Minimization) يمنع جمع بيانات زائدة عن حاجة الغرض المعلن.', '["تقليل","التقليل","تقليل البيانات"]'::jsonb, NULL, 'published'),
  ('lg-q1-4', 'lg-q1', 'lg-l3', 'match', 'medium', 'طابق كل ركن من أركان القرار الإداري بمعناه.', NULL, 'أركان القرار الإداري: الاختصاص، الشكل، السبب، المحل، والغاية؛ وتخلّف أي ركن يصيبه بعيب.', NULL, NULL, 'published'),
  ('lg-q1-5', 'lg-q1', 'lg-l3', 'order', 'hard', 'رتّب القواعد القانونية من الأعلى إلى الأدنى في التدرّج التشريعي.', NULL, 'التدرّج يبدأ من الدستور بوصفه أعلى القواعد وينتهي بالقرارات الفردية التنفيذية.', NULL, NULL, 'published'),
  ('lg-q1-6', 'lg-q1', 'lg-l2', 'mcq', 'hard', 'جهة جمعت بيانات المواطنين لغرض إصدار تصاريح ثم استخدمتها في حملة تسويقية. أي مبدأ خُولف أساساً؟', NULL, 'استخدام البيانات في غرض مغاير للغرض المعلن عند الجمع يخالف مبدأ تحديد الغرض بصورة مباشرة.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-7', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'بحسب المحاضرة، ماذا يجب أن يدرك الموظف إلى جانب إتقان استخدام النظام الإلكتروني؟', NULL, 'الثقافة القانونية لا تقل أهمية عن الكفاءة التقنية: لا يكفي معرفة الاستخدام، بل يجب إدراك الحدود القانونية والمسؤولية المترتبة على إساءة الاستخدام.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-8', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'الإدارة الإلكترونية تقوم على عنصرين أساسيين هما:', NULL, 'العنصر التقني (أجهزة وبرامج وشبكات) والعنصر البشري (موظفون مؤهلون) هما ركيزتا الإدارة الإلكترونية كما ورد في المحور الثاني.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-9', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'من أبرز نتائج الانتقال إلى الإدارة الإلكترونية وفق المحاضرة:', NULL, 'الانتقال يمكّن من مشاركة أوسع للموظفين وإعادة تنظيم أساليب العمل وإجراءات إنجاز المعاملات بما يلائم البيئة الرقمية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-10', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'الحكومة الإلكترونية بحسب المحاضرة:', NULL, 'النص: «الحكومة الإلكترونية لا تعني إنشاء حكومة جديدة... وإنما تعني أن الدولة تؤدي وظائفها التقليدية باستخدام وسائل إلكترونية حديثة».', '1'::jsonb, NULL, 'published'),
  ('lg-q1-11', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'أيّ مما يلي لم يُذكر ضمن تطبيقات التطور الإلكتروني في المحاضرة؟', NULL, 'التطبيقات المذكورة هي: الرواتب، الإجازات، الترقيات، شؤون الموظفين، المخازن، المشتريات، المراسلات، الأرشفة، حفظ البيانات، ومتابعة المعاملات — ولم تُذكر الانتخابات.', '2'::jsonb, NULL, 'published'),
  ('lg-q1-12', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'إذا سجّل النظام الإلكتروني خطأً أدى إلى استقطاع من راتب موظف، فإن هذا الخطأ:', NULL, 'دقة البيانات الإلكترونية وسلامتها مسألة قانونية لأنها ترتب حقوقًا والتزامات.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-13', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'من الأسئلة القانونية الجديدة التي تثيرها البيئة الإلكترونية بحسب المحاضرة:', NULL, 'من الأسئلة الست في المحور السادس: القيمة القانونية للمستند الإلكتروني، وتحديد من أدخل البيانات، وحجية المراسلات في الإثبات، والتحقق من الهوية، وصلاحية الوصول، والمسؤولية عن التعديل غير المشروع.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-14', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'من صور الأفعال غير المشروعة في البيئة الإلكترونية بحسب المحاضرة:', NULL, 'الدخول غير المصرّح به من صور الأفعال غير المشروعة، إلى جانب إتلاف البيانات والبرامج وتعطيل الأجهزة وانتحال الشخصية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-15', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'ما التحدي الذي يخلقه اعتماد المرفق العام على الأنظمة الإلكترونية بحسب المحاضرة؟', NULL, 'الاعتماد على التقنية يخلق تحديًا يتعلق بمبدأ استمرار المرفق العام بانتظام واطراد، إذ قد يؤدي توقف النظام أو اختراق الشبكة إلى اضطراب الخدمة.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-16', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'من إيجابيات التحول الإلكتروني في مجال الرقابة بحسب المحاضرة:', NULL, 'النظام الإلكتروني يمكنه تسجيل وقت الدخول ونوع الإجراء والشخص الذي قام به ووقت إحالة المعاملة، خلافًا لصعوبة ذلك في الإدارة الورقية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-17', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'كم عدد أنواع المعوقات التي صنّفتها المحاضرة للتحول الإلكتروني؟', NULL, 'أربعة أنواع: معوقات إدارية-تنظيمية، وقانونية، وتقنية-مالية، وبشرية.', '2'::jsonb, NULL, 'published'),
  ('lg-q1-18', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'ضعف الوعي الإلكتروني ومقاومة بعض الموظفين للتغيير يندرجان تحت أي نوع من المعوقات؟', NULL, 'هذان العاملان من صميم المعوقات البشرية إلى جانب قلة الكوادر المتخصصة وضعف التدريب.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-19', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'من التساؤلات القانونية التي يطرحها استخدام الذكاء الاصطناعي في الوظيفة العامة وفق المحاضرة:', NULL, 'من أبرز الأسئلة الستة: المسؤولية عن الخطأ الخوارزمي، وجواز الاعتماد على القرار الذكي، وحدود الرقابة البشرية، وضمان عدم التحيّز، وحماية البيانات، وحدود واجب المراجعة.', '0'::jsonb, NULL, 'published'),
  ('lg-q1-20', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'ما القاعدة الأساسية التي ختمت بها المحاضرة؟', NULL, 'القاعدة الختامية: التحول الرقمي يغيّر وسيلة أداء الوظيفة العامة، لكنه لا يلغي خضوع الإدارة والموظف للقانون؛ بل يفرض تطوير القواعد القانونية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-21', 'lg-q1', 'lg-l1', 'mcq', 'medium', 'نجاح التحول الإلكتروني بحسب خاتمة المحاضرة يتطلب الجمع بين:', NULL, 'الخاتمة: يتطلب النجاح الجمع بين الكفاءة التقنية والمشروعية القانونية، عبر تطوير الإجراءات وتأهيل الموظفين وحماية البيانات وضبط الصلاحيات.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-22', 'lg-q1', 'lg-l1', 'tf', 'medium', 'التحول في وسيلة أداء الوظيفة العامة يعني التحلل من أحكام القانون.', NULL, 'النص صريح: التحول «لا يعني التحلل من أحكام القانون، وإنما يفرض إعادة النظر في كيفية تطبيق بعض القواعد القانونية التقليدية».', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-23', 'lg-q1', 'lg-l1', 'tf', 'medium', 'اختفاء الموظف العام هو المقصود بمفهوم التطور الإلكتروني في الإدارة.', NULL, 'المقصود تغيّر طريقة أداء الموظف لمهامه وواجباته، لا اختفاء دوره.', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-24', 'lg-q1', 'lg-l1', 'tf', 'medium', 'التقنية في الإدارة الإلكترونية تُعد بديلًا عن القانون الذي يحكم النشاط الإداري.', NULL, 'النص واضح: «التقنية تظل وسيلة لأداء النشاط الإداري وليست بديلًا عن القانون الذي يحكم هذا النشاط».', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-25', 'lg-q1', 'lg-l1', 'tf', 'medium', 'يجب أن يواكب الانتقال إلى الإدارة الإلكترونية حماية حقوق الأفراد التي كفلها القانون.', NULL, 'صحيح — أكدت المحاضرة ضرورة أن يواكب هذا الانتقال حماية القانون وحقوق ومصالح الأفراد التي وضعها المشرّع.', 'true'::jsonb, NULL, 'published'),
  ('lg-q1-26', 'lg-q1', 'lg-l1', 'tf', 'medium', 'تؤثر الحكومة الإلكترونية في الوظيفة العامة من الناحية التنظيمية فقط دون أي بُعد قانوني.', NULL, 'غير صحيح — تؤثر من ناحيتين: تنظيمية (تغيّر أساليب العمل والهياكل) وقانونية (صحة الإجراءات وحماية البيانات والاختصاص والمسؤولية).', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-27', 'lg-q1', 'lg-l1', 'tf', 'medium', 'دقة البيانات المحفوظة إلكترونيًا تُعد مسألة قانونية وليست مجرد مسألة تقنية.', NULL, 'صحيح — مثال الاستقطاع الخاطئ من الراتب يوضح أن خطأ النظام ينعكس مباشرة على حق مالي للموظف، مما يجعل دقة البيانات مسألة قانونية.', 'true'::jsonb, NULL, 'published'),
  ('lg-q1-28', 'lg-q1', 'lg-l1', 'tf', 'medium', 'الموظف الذي يتجاوز صلاحياته الإلكترونية أو يفشي المعلومات لا يتحمل أي مسؤولية قانونية.', NULL, 'غير صحيح — النص يوضح أن ذلك «قد يرتكب مخالفة تستوجب مساءلته وفقًا للقواعد القانونية النافذة».', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-29', 'lg-q1', 'lg-l1', 'tf', 'medium', 'صيانة الأنظمة والنسخ الاحتياطي وخطط الطوارئ وتأهيل الموظفين مسائل غير ضرورية لضمان استمرار المرفق العام.', NULL, 'غير صحيح — النص يعتبرها مسائل «ترتبط بصورة مباشرة بضمان استمرار المرفق العام في أداء وظائفه».', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-30', 'lg-q1', 'lg-l1', 'tf', 'medium', 'ينبغي أن تتحول الرقابة الإلكترونية إلى وسيلة غير محدودة للتدخل في خصوصية الموظف.', NULL, 'غير صحيح — يجب التوازن بين حق الإدارة في الرقابة وحق الموظف في الخصوصية، وفي الحدود التي يسمح بها القانون.', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-31', 'lg-q1', 'lg-l1', 'tf', 'medium', 'قصور التشريعات عن مواكبة التوقيع الإلكتروني والإثبات وحماية البيانات يُعد من المعوقات القانونية.', NULL, 'صحيح — هذا بالضبط تعريف المعوقات القانونية الوارد في المحور التاسع.', 'true'::jsonb, NULL, 'published'),
  ('lg-q1-32', 'lg-q1', 'lg-l1', 'tf', 'medium', 'اعتبرت المحاضرة أن مسائل الذكاء الاصطناعي في الوظيفة العامة لا تحتاج إلى أي دراسة قانونية مستقلة.', NULL, 'غير صحيح — النص ينص على أنها «تحتاج إلى دراسة مستقلة نظرًا لما تثيره من إشكالات قانونية».', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-33', 'lg-q1', 'lg-l1', 'tf', 'medium', 'لا يفقد القرار الإداري طبيعته القانونية لمجرد صدوره أو تبليغه بوسيلة إلكترونية.', NULL, 'صحيح — نص صريح في الخاتمة يؤكد استمرار الطبيعة القانونية للقرار الإداري بصرف النظر عن وسيلة إصداره.', 'true'::jsonb, NULL, 'published'),
  ('lg-q1-34', 'lg-q1', 'lg-l1', 'open', 'hard', 'سجّل النظام الإلكتروني لأحد الموظفين تغيّبًا عن العمل نتيجة خطأ تقني، فتم استقطاع جزء من راتبه دون علمه. هل يبقى هذا خطأً تقنيًا بحتًا؟ وما الآلية الواجب توافرها لمعالجته، ومن يتحمل المسؤولية؟', 'سيناريو', 'الخطأ لا يبقى تقنيًا بحتًا؛ لأنه انعكس مباشرة على حق مالي للموظف فصار مسألة قانونية. وجوب توافر آلية قانونية وإدارية لمراجعة البيانات المسجّلة وتصحيحها ورد المبلغ المستقطع. تحديد الجهة أو الشخص المسؤول عن الخطأ (خلل في تصميم النظام أو خطأ في إدخال البيانات). الهدف حماية حق الموظف وفقًا للقواعد القانونية النافذة.', NULL, '[{"text":"الخطأ لا يبقى تقنيًا بحتًا؛ لأنه انعكس مباشرة على حق مالي للموظف فصار مسألة قانونية.","keywords":["حق مالي","قانوني","راتب","استقطاع","ينعكس","مالي"]},{"text":"وجوب توافر آلية قانونية وإدارية لمراجعة البيانات المسجّلة وتصحيحها ورد المبلغ المستقطع.","keywords":["الية","مراجعة","تصحيح","رد المبلغ","بيانات"]},{"text":"تحديد الجهة أو الشخص المسؤول عن الخطأ (خلل في تصميم النظام أو خطأ في إدخال البيانات).","keywords":["مسؤول","المسؤولية","ادخال","تصميم","تحديد"]},{"text":"الهدف حماية حق الموظف وفقًا للقواعد القانونية النافذة.","keywords":["حماية","حق الموظف","النافذة","القواعد"]}]'::jsonb, 'published'),
  ('lg-q1-35', 'lg-q1', 'lg-l1', 'open', 'hard', 'موظف يملك صلاحية دخول إلى نظام إلكتروني حكومي قام بنسخ بيانات سرّية متعلقة بمواطنين ونقلها إلى جهة خارجية دون إذن. حلّل الموقف في ضوء ما ورد عن أمن المعلومات والمسؤولية الوظيفية.', 'سيناريو', 'الفعل صورة من صور الأفعال غير المشروعة في البيئة الإلكترونية: إفشاء المعلومات ونقلها دون إذن. يخالف متطلبات أمن المعلومات: المحافظة على السرّية ومنع النقل أو التعديل غير المصرّح به. امتلاك صلاحية الدخول لا يبرر تجاوز حدود استخدامها؛ الموظف مسؤول عن احترام حدود وظيفته. الفعل يستوجب المساءلة القانونية وفق القواعد النافذة المتعلقة بحماية البيانات.', NULL, '[{"text":"الفعل صورة من صور الأفعال غير المشروعة في البيئة الإلكترونية: إفشاء المعلومات ونقلها دون إذن.","keywords":["افشاء","غير مشروع","دون اذن","نقل","سري"]},{"text":"يخالف متطلبات أمن المعلومات: المحافظة على السرّية ومنع النقل أو التعديل غير المصرّح به.","keywords":["امن المعلومات","سري","غير المصرح","منع"]},{"text":"امتلاك صلاحية الدخول لا يبرر تجاوز حدود استخدامها؛ الموظف مسؤول عن احترام حدود وظيفته.","keywords":["صلاحي","تجاوز","حدود","لا يبرر"]},{"text":"الفعل يستوجب المساءلة القانونية وفق القواعد النافذة المتعلقة بحماية البيانات.","keywords":["مساءل","مسؤولية","قانون","حماية البيانات"]}]'::jsonb, 'published'),
  ('lg-q1-36', 'lg-q1', 'lg-l1', 'open', 'hard', 'تعرّضت شبكة إحدى الدوائر الحكومية للاختراق، مما أدى إلى توقف خدمة إلكترونية عن المواطنين لعدة أيام. اربط الموقف بمفهوم استمرار المرفق العام، واذكر الإجراءات الوقائية التي أشارت إليها المحاضرة.', 'سيناريو', 'الموقف يمسّ مباشرة مبدأ استمرار المرفق العام بانتظام واطراد. الاعتماد الأساسي على الأنظمة الإلكترونية يجعل الخدمة عرضة للتوقف عند الاختراق أو فقدان البيانات. الإجراءات الوقائية: صيانة الأنظمة وحماية البيانات وإنشاء النسخ الاحتياطية. وضع خطط للطوارئ وتأهيل الموظفين لضمان استمرار المرفق في أداء وظائفه.', NULL, '[{"text":"الموقف يمسّ مباشرة مبدأ استمرار المرفق العام بانتظام واطراد.","keywords":["استمرار","المرفق","انتظام","اطراد"]},{"text":"الاعتماد الأساسي على الأنظمة الإلكترونية يجعل الخدمة عرضة للتوقف عند الاختراق أو فقدان البيانات.","keywords":["اختراق","توقف","فقدان","اعتماد","اضطراب"]},{"text":"الإجراءات الوقائية: صيانة الأنظمة وحماية البيانات وإنشاء النسخ الاحتياطية.","keywords":["صيان","نسخ","احتياطي","حماية البيانات"]},{"text":"وضع خطط للطوارئ وتأهيل الموظفين لضمان استمرار المرفق في أداء وظائفه.","keywords":["طوارئ","تاهيل","خطط","تدريب"]}]'::jsonb, 'published'),
  ('lg-q1-37', 'lg-q1', 'lg-l1', 'open', 'hard', 'طوّرت إحدى الجهات نظامًا يعتمد على الذكاء الاصطناعي لاتخاذ قرار آلي بشأن ترقية الموظفين بناءً على تحليل بياناتهم الوظيفية. ناقش المخاطر القانونية المحتملة لهذا القرار.', 'سيناريو', 'تحديد المسؤولية إذا صدر قرار الترقية أو رفضها بصورة خاطئة نتيجة خلل في النظام. مدى جواز الاعتماد على النظام الذكي في قرار يمسّ المركز القانوني للموظف دون رقابة بشرية كافية. ضمان عدم تحيّز الخوارزمية المستخدمة في تحليل بيانات الموظفين. حماية بيانات الموظفين من الاستخدام أو الإفشاء غير المشروع. هذه المسائل تحتاج إلى دراسة قانونية مستقلة لحساسيتها وأثرها على حقوق الموظفين.', NULL, '[{"text":"تحديد المسؤولية إذا صدر قرار الترقية أو رفضها بصورة خاطئة نتيجة خلل في النظام.","keywords":["مسؤولي","خطا","خلل","ترقي"]},{"text":"مدى جواز الاعتماد على النظام الذكي في قرار يمسّ المركز القانوني للموظف دون رقابة بشرية كافية.","keywords":["رقابة بشري","المركز القانوني","اشراف","جواز"]},{"text":"ضمان عدم تحيّز الخوارزمية المستخدمة في تحليل بيانات الموظفين.","keywords":["تحيز","خوارزم","عدال","ضمان"]},{"text":"حماية بيانات الموظفين من الاستخدام أو الإفشاء غير المشروع.","keywords":["حماية البيانات","افشاء","سري"]},{"text":"هذه المسائل تحتاج إلى دراسة قانونية مستقلة لحساسيتها وأثرها على حقوق الموظفين.","keywords":["دراس","مستقل","حقوق"]}]'::jsonb, 'published'),
  ('lg-q1-38', 'lg-q1', 'lg-l1', 'open', 'hard', 'موظف استخدم صلاحياته الإلكترونية للاطلاع على بيانات زميل لا علاقة لها بعمله، ثم شاركها مع شخص آخر داخل الدائرة. كيّف هذا التصرف قانونيًا وفق ما ورد في المحاضرة.', 'سيناريو', 'التصرف يتجاوز حدود الصلاحيات الإلكترونية الممنوحة للموظف. يندرج ضمن الإخلال بواجب المحافظة على سرّية المعلومات والوصول غير المصرّح به. استخدام الصلاحية لغير الغرض الوظيفي المشروع لا يبرره مجرد امتلاكها. يستوجب المساءلة وفق القواعد القانونية النافذة.', NULL, '[{"text":"التصرف يتجاوز حدود الصلاحيات الإلكترونية الممنوحة للموظف.","keywords":["تجاوز","صلاحي","حدود"]},{"text":"يندرج ضمن الإخلال بواجب المحافظة على سرّية المعلومات والوصول غير المصرّح به.","keywords":["سري","وصول","غير المصرح","اخلال"]},{"text":"استخدام الصلاحية لغير الغرض الوظيفي المشروع لا يبرره مجرد امتلاكها.","keywords":["الغرض","وظيفي","مشروع","لا يبرر"]},{"text":"يستوجب المساءلة وفق القواعد القانونية النافذة.","keywords":["مساءل","قانون","مسؤولي","النافذة"]}]'::jsonb, 'published'),
  ('lg-q1-39', 'lg-q1', 'lg-l1', 'open', 'hard', 'دائرة حكومية اعتمدت أرشفة إلكترونية لكل معاملاتها، لكنها لم تُنشئ نسخًا احتياطية دورية، وتعرّض النظام لعطل أدى إلى فقدان جزء من الوثائق. ما أوجه القصور، وما الذي كان ينبغي توفره؟', 'سيناريو', 'الإخلال بمتطلبات نجاح الأرشفة الإلكترونية الواردة في المحاضرة. غياب النسخ الاحتياطية الدورية وتحديث وسائل التخزين والأجهزة والبرامج. المساس بسلامة الوثيقة وإمكان الرجوع إليها وإثبات صحتها وحمايتها من الإتلاف. غياب خطة طوارئ تضمن استمرار المرفق العام بانتظام واطراد.', NULL, '[{"text":"الإخلال بمتطلبات نجاح الأرشفة الإلكترونية الواردة في المحاضرة.","keywords":["ارشف","متطلبات","نجاح"]},{"text":"غياب النسخ الاحتياطية الدورية وتحديث وسائل التخزين والأجهزة والبرامج.","keywords":["نسخ","احتياطي","تحديث","تخزين"]},{"text":"المساس بسلامة الوثيقة وإمكان الرجوع إليها وإثبات صحتها وحمايتها من الإتلاف.","keywords":["سلام","وثيق","اثبات","اتلاف","الرجوع"]},{"text":"غياب خطة طوارئ تضمن استمرار المرفق العام بانتظام واطراد.","keywords":["طوارئ","استمرار","المرفق","اطراد"]}]'::jsonb, 'published'),
  ('lg-q1-40', 'lg-q1', 'lg-l1', 'open', 'hard', 'اشرح لماذا يُعد التحول الإلكتروني في الوظيفة العامة امتدادًا قانونيًا وليس مجرد تطور تقني بحت، مستندًا إلى ما ورد في المحاضرة.', 'مقالي', 'الإدارة تبقى خاضعة للقواعد القانونية التي تحكم نشاطها رغم استخدام الوسائل الإلكترونية. التقنية وسيلة لأداء النشاط الإداري وليست بديلًا عن القانون. القرار الذي يصدر إلكترونيًا يجب أن يستند إلى اختصاص قانوني. اتساع استخدام التقنية يفرز مسائل قانونية جديدة: قيمة المستند الإلكتروني، والتوقيع، والإثبات، وحماية البيانات. يستلزم ذلك إعادة النظر في تطبيق القواعد التقليدية ووضع تنظيم قانوني للبيئة الإلكترونية.', NULL, '[{"text":"الإدارة تبقى خاضعة للقواعد القانونية التي تحكم نشاطها رغم استخدام الوسائل الإلكترونية.","keywords":["خاضع","قانون","تحكم","نشاط"]},{"text":"التقنية وسيلة لأداء النشاط الإداري وليست بديلًا عن القانون.","keywords":["وسيل","بديل","تقني"]},{"text":"القرار الذي يصدر إلكترونيًا يجب أن يستند إلى اختصاص قانوني.","keywords":["اختصاص","قرار","يستند"]},{"text":"اتساع استخدام التقنية يفرز مسائل قانونية جديدة: قيمة المستند الإلكتروني، والتوقيع، والإثبات، وحماية البيانات.","keywords":["مستند","توقيع","اثبات","حماية البيانات","مسائل"]},{"text":"يستلزم ذلك إعادة النظر في تطبيق القواعد التقليدية ووضع تنظيم قانوني للبيئة الإلكترونية.","keywords":["اعادة النظر","تنظيم","تقليدي","تشريع"]}]'::jsonb, 'published'),
  ('lg-q1-41', 'lg-q1', 'lg-l1', 'open', 'hard', 'وضّح العلاقة بين الحكومة الإلكترونية والوظيفة العامة من الناحيتين التنظيمية والقانونية كما وردت في المحاضرة.', 'مقالي', 'الحكومة الإلكترونية لا تعني إنشاء حكومة جديدة؛ الدولة تؤدي وظائفها التقليدية بوسائل إلكترونية حديثة. الجهة الإدارية تبقى ذاتها واختصاصاتها تستند إلى القانون. الموظف العام يبقى خاضعًا للنظام القانوني للوظيفة العامة. الناحية التنظيمية: تغيّر أساليب العمل والهياكل والإجراءات. الناحية القانونية: تثير مسائل صحة الإجراءات والمستندات وحماية البيانات والاختصاص والمسؤولية.', NULL, '[{"text":"الحكومة الإلكترونية لا تعني إنشاء حكومة جديدة؛ الدولة تؤدي وظائفها التقليدية بوسائل إلكترونية حديثة.","keywords":["جديد","وظائف","تقليدي","الدول"]},{"text":"الجهة الإدارية تبقى ذاتها واختصاصاتها تستند إلى القانون.","keywords":["الجهة","اختصاص","تستند","ذاتها"]},{"text":"الموظف العام يبقى خاضعًا للنظام القانوني للوظيفة العامة.","keywords":["الموظف","خاضع","النظام القانوني"]},{"text":"الناحية التنظيمية: تغيّر أساليب العمل والهياكل والإجراءات.","keywords":["تنظيمي","اساليب","هياكل","اجراءات"]},{"text":"الناحية القانونية: تثير مسائل صحة الإجراءات والمستندات وحماية البيانات والاختصاص والمسؤولية.","keywords":["قانوني","صح","حماية","المسؤولي"]}]'::jsonb, 'published'),
  ('lg-q1-42', 'lg-q1', 'lg-l1', 'open', 'hard', 'ناقش أهم المعوقات التي تواجه التحول الإلكتروني في الوظيفة العامة، مبيّنًا العلاقة بين المعوقات القانونية والمعوقات البشرية.', 'مقالي', 'المعوقات الإدارية والتنظيمية: ضعف التخطيط والتنسيق وتعقيد الإجراءات وعدم وضوح الاستراتيجية. المعوقات القانونية: قصور التشريعات عن مواكبة التوقيع الإلكتروني والإثبات وحماية البيانات. المعوقات التقنية والمالية: ضعف البنية التحتية وارتفاع تكاليف الإنشاء والصيانة. المعوقات البشرية: ضعف الوعي الإلكتروني ومقاومة التغيير وضعف التدريب وقلة الكوادر. الربط بينهما: التقاء الثقافة القانونية بالثقافة التقنية شرط لتفعيل النصوص عمليًا.', NULL, '[{"text":"المعوقات الإدارية والتنظيمية: ضعف التخطيط والتنسيق وتعقيد الإجراءات وعدم وضوح الاستراتيجية.","keywords":["اداري","تنظيمي","تخطيط","تنسيق","استراتيجي"]},{"text":"المعوقات القانونية: قصور التشريعات عن مواكبة التوقيع الإلكتروني والإثبات وحماية البيانات.","keywords":["قانوني","تشريع","توقيع","اثبات","قصور"]},{"text":"المعوقات التقنية والمالية: ضعف البنية التحتية وارتفاع تكاليف الإنشاء والصيانة.","keywords":["تقني","مالي","بني","تكاليف","صيان"]},{"text":"المعوقات البشرية: ضعف الوعي الإلكتروني ومقاومة التغيير وضعف التدريب وقلة الكوادر.","keywords":["بشري","وعي","مقاوم","تدريب","كوادر"]},{"text":"الربط بينهما: التقاء الثقافة القانونية بالثقافة التقنية شرط لتفعيل النصوص عمليًا.","keywords":["الثقافة القانوني","الثقافة التقني","التقاء","تفعيل"]}]'::jsonb, 'published'),
  ('lg-q1-43', 'lg-q1', 'lg-l1', 'open', 'hard', 'بيّن الإشكاليات القانونية التي يثيرها استخدام الذكاء الاصطناعي في أداء الوظيفة العامة، ولماذا تحتاج إلى دراسة قانونية مستقلة بحسب المحاضرة.', 'مقالي', 'المسؤولية عن الخطأ الناتج عن نظام يعتمد على الذكاء الاصطناعي. مدى جواز الاعتماد على النظام الذكي في قرار يمسّ المركز القانوني للموظف أو المواطن. حدود الرقابة البشرية على القرارات التي تقترحها الأنظمة الذكية. ضمان عدم تحيّز الخوارزميات وحماية البيانات التي تستخدمها. الحاجة إلى دراسة مستقلة لأن الذكاء الاصطناعي يتجاوز الأتمتة التقليدية إلى التحليل والتنبؤ والاستدلال.', NULL, '[{"text":"المسؤولية عن الخطأ الناتج عن نظام يعتمد على الذكاء الاصطناعي.","keywords":["مسؤولي","خطا","خوارزم"]},{"text":"مدى جواز الاعتماد على النظام الذكي في قرار يمسّ المركز القانوني للموظف أو المواطن.","keywords":["قرار","المركز القانوني","جواز","يمس"]},{"text":"حدود الرقابة البشرية على القرارات التي تقترحها الأنظمة الذكية.","keywords":["رقابة بشري","حدود","اشراف"]},{"text":"ضمان عدم تحيّز الخوارزميات وحماية البيانات التي تستخدمها.","keywords":["تحيز","حماية البيانات","ضمان"]},{"text":"الحاجة إلى دراسة مستقلة لأن الذكاء الاصطناعي يتجاوز الأتمتة التقليدية إلى التحليل والتنبؤ والاستدلال.","keywords":["دراس","مستقل","تنبؤ","استدلال","تحليل"]}]'::jsonb, 'published'),
  ('lg-q1-44', 'lg-q1', 'lg-l1', 'open', 'hard', 'ناقش العلاقة بين الثقافة القانونية والثقافة التقنية بالنسبة للموظف العام في ضوء ما ورد في المحاضرة عن المعوقات البشرية.', 'مقالي', 'لا يكفي إتقان استخدام النظام تقنيًا. معرفة حدود الصلاحيات وما يجوز وما لا يجوز للموظف فعله. إدراك واجبات التعامل مع البيانات والمسؤولية المترتبة على إساءة الاستخدام. الجمع بين التدريب التقني والتأهيل القانوني شرط لتجاوز المعوقات البشرية.', NULL, '[{"text":"لا يكفي إتقان استخدام النظام تقنيًا.","keywords":["لا يكفي","تقني","اتقان","استخدام"]},{"text":"معرفة حدود الصلاحيات وما يجوز وما لا يجوز للموظف فعله.","keywords":["حدود","صلاحي","يجوز"]},{"text":"إدراك واجبات التعامل مع البيانات والمسؤولية المترتبة على إساءة الاستخدام.","keywords":["بيانات","مسؤولي","اساء","واجبات"]},{"text":"الجمع بين التدريب التقني والتأهيل القانوني شرط لتجاوز المعوقات البشرية.","keywords":["تدريب","تاهيل","الجمع","بشري"]}]'::jsonb, 'published'),
  ('lg-q1-45', 'lg-q1', 'lg-l1', 'open', 'hard', 'في ضوء التساؤلات القانونية التي أثارها انتقال الوظيفة العامة نحو استخدام الذكاء الاصطناعي، اقترح ثلاثة ضوابط أساسية ينبغي أن تلتزم بها أي دائرة حكومية قبل اعتماد نظام ذكاء اصطناعي في اتخاذ قراراتها.', 'مقالي', 'إبقاء القرار النهائي بيد موظف مسؤول (الإشراف البشري). وضوح آلية تحديد المسؤولية عند وقوع الخطأ. التحقق الدوري من عدم تحيّز النظام. حماية البيانات التي يعالجها النظام وضبط صلاحيات الوصول إليها.', NULL, '[{"text":"إبقاء القرار النهائي بيد موظف مسؤول (الإشراف البشري).","keywords":["القرار النهائي","اشراف","بشري","موظف مسؤول"]},{"text":"وضوح آلية تحديد المسؤولية عند وقوع الخطأ.","keywords":["الي","مسؤولي","خطا","تحديد"]},{"text":"التحقق الدوري من عدم تحيّز النظام.","keywords":["تحيز","تحقق","دوري"]},{"text":"حماية البيانات التي يعالجها النظام وضبط صلاحيات الوصول إليها.","keywords":["حماية البيانات","صلاحي","وصول","ضبط"]}]'::jsonb, 'published'),
  ('lg-q1-46', 'lg-q1', 'lg-l3', 'mcq', 'easy', 'ما الفرق بين الحكومة الإلكترونية (E-Government) والحوكمة الإلكترونية (E-Governance)؟', NULL, 'الحكومة الإلكترونية تركّز على الاستخدام التكاملي للتقنية في التعاملات، بينما الحوكمة الإلكترونية مفهوم أشمل يتأثر بمفاهيم الحكم الراشد والحاكمية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-47', 'lg-q1', 'lg-l3', 'tf', 'easy', 'تختلف مشروعية القرار الإداري باختلاف الوسيلة التي استُخدمت لإصداره، فالقرار الإلكتروني لا يخضع لنفس شروط القرار الورقي.', NULL, 'القاعدة الأساسية أن مشروعية العمل الإداري لا تختلف بسبب الوسيلة؛ فالقرار الإلكتروني يجب أن تتوافر فيه جميع شروط المشروعية ذاتها التي تتوافر في القرار الورقي.', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-48', 'lg-q1', 'lg-l3', 'match', 'medium', 'طابق كل بُعد من أبعاد مبدأ المشروعية في الإدارة الرقمية بوصفه.', NULL, 'أبعاد المشروعية الخمسة في المحاضرة هي: الاختصاص، الشكل والإجراءات، السبب، المحل، والغاية.', NULL, NULL, 'published'),
  ('lg-q1-49', 'lg-q1', 'lg-l3', 'fill', 'medium', 'القرار الذي يُنتج كلياً أو جزئياً بواسطة نظام إلكتروني وفق مجموعة من القواعد أو الخوارزميات يسمّى القرار الإداري ............', NULL, 'القرار الإداري المؤتمت يختلف عن القرار الإلكتروني العادي في أنه يُنتج آلياً وفق خوارزميات محددة دون تدخل بشري مباشر في كل حالة.', '["المؤتمت","مؤتمت"]'::jsonb, NULL, 'published'),
  ('lg-q1-50', 'lg-q1', 'lg-l3', 'mcq', 'medium', 'هل تملك المنصة الإلكترونية الإدارية سلطة إدارية بذاتها؟', NULL, 'الإجابة القانونية الأدق أن المنصة لا تملك سلطة إدارية بذاتها، وإنما هي وسيلة تقنية، ومصدر السلطة يبقى القانون.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-51', 'lg-q1', 'lg-l3', 'mcq', 'medium', 'الخطأ الخوارزمي (Algorithmic Error) يعني أن:', NULL, 'القاعدة الأساسية: صحة العملية التقنية لا تعني بالضرورة مشروعية النتيجة القانونية.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-52', 'lg-q1', 'lg-l3', 'order', 'hard', 'رتّب سلسلة صناعة القرار الرقمي كما وردت في المحاضرة، من نقطة البداية (المشرّع) إلى القرار النهائي.', NULL, 'هذه السلسلة توضح أن المسؤولية عن القرار الإلكتروني يجب بحثها في كل مرحلة من مراحل صناعته، لا الاكتفاء بمساءلة الخوارزمية وحدها.', NULL, NULL, 'published'),
  ('lg-q1-53', 'lg-q1', 'lg-l3', 'mcq', 'medium', 'من أدوات إثبات حجية السجل الإلكتروني التي ذكرتها المحاضرة؟', NULL, 'من أدوات إثبات حجية السجل الإلكتروني: التوقيع الإلكتروني، الطابع الزمني، سجلات الدخول، سجل العمليات، والنسخ المحفوظة للقرارات.', '0'::jsonb, NULL, 'published'),
  ('lg-q1-54', 'lg-q1', 'lg-l3', 'tf', 'medium', 'من حق الشخص المتضرر من قرار إلكتروني مخالف للقانون أن تتوافر له وسائل الاعتراض والطعن المناسبة وفق النظام القانوني المختص.', NULL, 'لا يجوز أن يؤدي التحول الرقمي إلى إلغاء حق الأفراد في الرقابة القضائية، ويشمل ذلك حق التظلم والطعن أمام القضاء المختص.', 'true'::jsonb, NULL, 'published'),
  ('lg-q1-55', 'lg-q1', 'lg-l3', 'open', 'hard', 'منصة حكومية إلكترونية رفضت طلب مواطن للحصول على ترخيص دون بيان سبب الرفض أو الجهة التي أصدرت القرار أو آلية الاعتراض. حلّل هذا الموقف من زاوية مبدأي الشفافية وحق الطعن، ووضّح ما ينبغي أن تتضمنه إجابة المنصة لتكون مشروعة.', 'سيناريو', 'الموقف يخالف مبدأ الشفافية؛ فالقرار المشروع يجب أن يتضمن سبب الرفض، الجهة المصدرة، الأساس القانوني، البيانات المعتمدة، وآلية الاعتراض أو الطعن.', NULL, '[{"text":"الموقف يخالف مبدأ الشفافية المطلوب في الإدارة الرقمية؛ إذ يحق للمواطن معرفة سبب الرفض، والجهة التي أصدرت القرار، والأساس القانوني، والبيانات التي بُني عليها القرار، وكيفية الاعتراض أو الطعن. القرار المشروع يجب أن يتضمن هذه العناصر مجتمعة حتى لو كان صادراً عن نظام مؤتمت.","keywords":["الشفافية","سبب الرفض","الطعن","الجهة المصدرة"]}]'::jsonb, 'published'),
  ('lg-q1-56', 'lg-q1', 'lg-l3', 'open', 'hard', 'ناقش العبارة التالية الواردة في المحاضرة: «التكنولوجيا الرقمية تغيّر وسيلة ممارسة الإدارة، لا تُخضِع الإدارة للقانون». اربط مناقشتك بمبدأ المشروعية وبمسؤولية الجهات المختلفة عن القرار الإلكتروني.', 'مقالي', 'نقاط للتوجيه: التمييز بين الوسيلة (التقنية) ومصدر السلطة (القانون)، وبقاء الإدارة الرقمية خاضعة لشروط المشروعية الخمسة، وتوزّع المسؤولية على أطراف سلسلة صناعة القرار لا على الخوارزمية وحدها.', NULL, '[{"text":"نقاط للتوجيه: التمييز بين الوسيلة (المنصة/الخوارزمية) ومصدر السلطة (القانون)؛ بيان أن انتقال الإدارة إلى البيئة الرقمية لا يعفيها من شروط المشروعية الخمسة؛ الإشارة إلى أن المسؤولية تظل موزعة على الإدارة والموظف ومصمم النظام بحسب مصدر الخطأ، لا على الخوارزمية بوصفها شخصاً قانونياً.","keywords":["مبدأ المشروعية","مصدر السلطة","المسؤولية","الخوارزمية"]}]'::jsonb, 'published'),
  ('lg-q1-57', 'lg-q1', 'lg-l4', 'mcq', 'easy', 'بحسب المادة (1) من القانون العراقي رقم (78) لسنة 2012، ما تعريف المعاملات الإلكترونية؟', NULL, 'عرّف المشرّع العراقي المعاملات الإلكترونية بأنها الطلبات والمستندات والمعاملات التي تتم بوسائل إلكترونية، وهو تعريف أوسع من العقد الإلكتروني وحده.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-58', 'lg-q1', 'lg-l4', 'match', 'medium', 'طابق كل مبدأ من مبادئ المعاملات الإلكترونية بمضمونه.', NULL, 'هذه المبادئ الثلاثة اعتمدتها أعمال الأونسيترال وتشكل أساس قانون التجارة الإلكترونية الحديث.', NULL, NULL, 'published'),
  ('lg-q1-59', 'lg-q1', 'lg-l4', 'tf', 'medium', 'جعل المشرّع العراقي نطاق تطبيق قانون المعاملات الإلكترونية مطلقاً دون أي استثناءات.', NULL, 'استثنى القانون مسائل مثل الأحوال الشخصية والوقف والتصرفات العقارية وإجراءات المحاكم وما يشترط توثيقه لدى الكاتب العدل، فالمشرّع لم يتبنَّ الرقمنة المطلقة.', 'false'::jsonb, NULL, 'published'),
  ('lg-q1-60', 'lg-q1', 'lg-l4', 'order', 'hard', 'رتّب مراحل عمل التوقيع الرقمي فنياً من البداية إلى النهاية.', NULL, 'إذا تطابقت القيمتان بعد المقارنة فذلك يعني سلامة الوثيقة وصحة التوقيع معاً؛ أما اختلافهما فيدل على احتمال تغيير الوثيقة أو التوقيع.', NULL, NULL, 'published'),
  ('lg-q1-61', 'lg-q1', 'lg-l4', 'mcq', 'hard', 'أي العبارات التالية تصف بدقة العلاقة بين التوقيع الإلكتروني والتوقيع الرقمي؟', NULL, 'التوقيع الإلكتروني مفهوم قانوني واسع، بينما التوقيع الرقمي مفهوم تقني أخص يعتمد عادة على تقنيات التشفير بالمفتاح العام (PKI).', '1'::jsonb, NULL, 'published'),
  ('lg-q1-62', 'lg-q1', 'lg-l4', 'fill', 'medium', 'بحسب المادة (5) من القانون العراقي، يجب أن يكون التوقيع الإلكتروني مرتبطاً بـ ............ وحده حتى تكون له قوة إثباتية.', NULL, 'من أهم ضمانات القوة الإثباتية للتوقيع الإلكتروني وفق المادة (5): ارتباط التوقيع بالموقِّع وحده، وسيطرته على وسيلة إنشائه، وإمكانية كشف التغيير فيه.', '["الموقِّع","الموقع","صاحبه"]'::jsonb, NULL, 'published'),
  ('lg-q1-63', 'lg-q1', 'lg-l4', 'mcq', 'medium', 'ما المقصود بسلسلة الحيازة الرقمية (Digital Chain of Custody)؟', NULL, 'سلسلة الحيازة الرقمية سجل دقيق يوثّق من أنشأ الدليل ومن حازه وأين حُفظ ومتى نُقل وهل عُدِّل، لضمان سلامته وعدم التلاعب به قبل عرضه أمام القضاء.', '1'::jsonb, NULL, 'published'),
  ('lg-q1-64', 'lg-q1', 'lg-l4', 'mcq', 'medium', 'إذا قدّم أحد الخصوم بريداً إلكترونياً كدليل على إبرام عقد، فأي سؤال ينبغي أن يكون محورياً وفق المحاضرة؟', NULL, 'لا ينبغي أن يكون السؤال القضائي شكلياً عن كون الوسيلة إلكترونية، بل ينبغي فحص الأصالة والسلامة والموثوقية عبر أسئلة مثل: من أرسلها؟ وهل الحساب تابع للمرسل؟ وهل تعرضت للتعديل؟ وهل توجد سجلات خادم أو رسائل مرتبطة تؤيدها؟', '1'::jsonb, NULL, 'published'),
  ('lg-q1-65', 'lg-q1', 'lg-l4', 'open', 'hard', 'أرسلت شركة عقداً إلكترونياً موقّعاً إلى شركة أخرى بقيمة مليار دينار، وبعد سنة حصل نزاع، إذ أنكرت الشركة الثانية توقيعها على العقد. بيّن لماذا لا يكفي أن يكون السؤال القضائي «هل العقد إلكتروني؟»، واذكر أربعة على الأقل من الأسئلة الثمانية التي ينبغي أن يطرحها القاضي للفصل في هذا النزاع.', 'سيناريو', 'القاعدة الجوهرية: الدليل الإلكتروني لا تثبت قوته من شكله الإلكتروني، وإنما من درجة موثوقية البيئة التقنية والقانونية التي أنشأته وحفظته.', NULL, '[{"text":"نقاط للتوجيه: التمييز بين الشكل الإلكتروني للعقد ودرجة موثوقية بيئته التقنية والقانونية؛ ذكر أسئلة من قبيل: هل الوثيقة أصلية؟ هل التوقيع مرتبط بالشخص المدَّعى صدوره عنه؟ هل كانت وسيلة التوقيع تحت سيطرته؟ هل عُدِّل العقد بعد التوقيع؟ هل كانت الشهادة الرقمية نافذة وقت التوقيع؟ هل يوجد ختم زمني؟ هل توجد سجلات تقنية تؤيد عملية التوقيع؟ هل يمكن للخبير الفني إعادة التحقق من التوقيع؟","keywords":["الأصالة","سيطرة الموقّع","الشهادة الرقمية","الختم الزمني","الخبير الفني"]}]'::jsonb, 'published'),
  ('cs-q1-1', 'cs-q1', 'cs-l1', 'mcq', 'easy', 'ما الذي تعنيه «السلامة» ضمن ثلاثية الأمن السيبراني؟', NULL, 'السلامة (Integrity) تعني عدم المساس بدقة البيانات واكتمالها إلا بتصريح موثّق.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-2', 'cs-q1', 'cs-l1', 'tf', 'easy', 'المخاطر السيبرانية مسؤولية الإدارة التقنية وحدها.', NULL, 'المخاطر السيبرانية مخاطر مؤسسية تقع مسؤوليتها النهائية على الإدارة العليا ومجلس الإدارة.', 'false'::jsonb, NULL, 'published'),
  ('cs-q1-3', 'cs-q1', 'cs-l2', 'fill', 'medium', 'المرحلة التي يتم فيها عزل أثر الحادث ومنع انتشاره تسمّى مرحلة ............', NULL, 'الاحتواء يلي الاكتشاف مباشرة، وهدفه الحدّ من انتشار الأثر قبل الاستئصال والتعافي.', '["الاحتواء","احتواء"]'::jsonb, NULL, 'published'),
  ('cs-q1-4', 'cs-q1', 'cs-l1', 'match', 'medium', 'طابق كل مصطلح بتعريفه الصحيح.', NULL, 'الخطر السيبراني ينشأ من التقاء تهديد بثغرة، ويُقاس بالاحتمال والأثر، ويُعالَج بالضوابط.', NULL, NULL, 'published'),
  ('cs-q1-5', 'cs-q1', 'cs-l2', 'order', 'hard', 'رتّب مراحل الاستجابة للحادث السيبراني بالترتيب الصحيح.', NULL, 'دورة الاستجابة تبدأ بالتحضير المسبق وتنتهي بتوثيق الدروس المستفادة لتحديث الضوابط.', NULL, NULL, 'published'),
  ('cs-q1-6', 'cs-q1', 'cs-l1', 'mcq', 'hard', 'ما الفرق الجوهري بين الحوكمة السيبرانية والعمليات الأمنية؟', NULL, 'الحوكمة طبقة توجيه ومساءلة ورقابة، بينما العمليات الأمنية هي التنفيذ التشغيلي اليومي للضوابط.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-7', 'cs-q1', 'cs-l1', 'mcq', 'easy', 'ما تعريف الأمن السيبراني؟', NULL, 'الأمن السيبراني نطاقه أوسع من أداة واحدة، ويشمل حماية الأجهزة والبرمجيات والشبكات والبيانات وحتى سلوك المستخدمين.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-8', 'cs-q1', 'cs-l1', 'match', 'medium', 'طابق كل مبدأ من مبادئ أمن المعلومات بتعريفه.', NULL, 'هذه المبادئ الأربعة تكمّل مثلث CIA، والمساءلة هي المهمة التي تربط الأمن السيبراني بالحوكمة مباشرة.', NULL, NULL, 'published'),
  ('cs-q1-9', 'cs-q1', 'cs-l1', 'tf', 'easy', 'الهندسة الاجتماعية تستغل الثغرات التقنية في الأنظمة بدلاً من استغلال السلوك البشري.', NULL, 'الهندسة الاجتماعية على العكس: تستغل الثقة والسلوك البشري بدلاً من الثغرات التقنية.', 'false'::jsonb, NULL, 'published'),
  ('cs-q1-10', 'cs-q1', 'cs-l1', 'fill', 'medium', 'أي مصدر محتمل يمكن أن يستغل ثغرة لإحداث ضرر يسمّى ............', NULL, 'التهديد (Threat) هو المصدر المحتمل للضرر، بينما الثغرة (Vulnerability) هي نقطة الضعف التي يستغلها.', '["التهديد","تهديد"]'::jsonb, NULL, 'published'),
  ('cs-q1-11', 'cs-q1', 'cs-l1', 'mcq', 'medium', 'أي مما يلي ليس من أصحاب المصلحة الأساسيين في حوكمة أمن المعلومات بحسب المحاضرة؟', NULL, 'أصحاب المصلحة الرئيسيون هم مجلس الإدارة، الإدارة التنفيذية، CISO، والموظفون؛ لا جهة خارجية غير مرتبطة بأنظمة المؤسسة.', '2'::jsonb, NULL, 'published'),
  ('cs-q1-12', 'cs-q1', 'cs-l1', 'order', 'hard', 'رتّب هذه الجهات في سلسلة حوكمة أمن المعلومات من الأعلى توجيهاً إلى الأقرب من التنفيذ اليومي.', NULL, 'مجلس الإدارة يضع التوجهات العليا، فتترجمها الإدارة التنفيذية إلى استراتيجيات، ويقودها CISO تنفيذياً، ويلتزم بها الموظفون في الممارسة اليومية.', NULL, NULL, 'published'),
  ('cs-q1-13', 'cs-q1', 'cs-l1', 'mcq', 'medium', 'ما الفرق الجوهري بين الحوكمة الإلكترونية العامة وحوكمة أمن المعلومات؟', NULL, 'حوكمة أمن المعلومات ليست مفهوماً منفصلاً، بل امتداد متخصص لمفهوم الحوكمة المؤسسية العامة يركّز على حماية المعلومات والأنظمة.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-14', 'cs-q1', 'cs-l1', 'open', 'hard', 'مؤسسة تعرّضت لاختراق أدى إلى تسريب بيانات عملاء، وتبيّن أن السبب تأخّر تطبيق تحديث أمني معروف منذ أشهر رغم توفره. بأي ركن من أركان الحوكمة الستة يرتبط هذا التقصير، وكيف تُعالَج المشكلة على مستوى الحوكمة لا الإدارة فقط؟', 'سيناريو', 'التقصير يرتبط بركني «إدارة المخاطر» و«قياس الأداء»، ومعالجته على مستوى الحوكمة تتطلب سياسة إلزامية ومؤشر أداء دوري لتحديثات الأمان، لا مجرد إصلاح تقني بعد الحادث.', NULL, '[{"text":"التقصير يرتبط بشكل أساسي بركني «إدارة المخاطر» و«قياس الأداء» (وربما «السياسات والمعايير» إن لم تكن هناك سياسة تحديثات واضحة). على مستوى الحوكمة، يجب أن يضع المجلس/الإدارة العليا سياسة إلزامية لتحديث الأنظمة ومؤشر أداء دوري يقاس به زمن تطبيق التحديثات الحرجة، لا الاكتفاء بمعالجة الثغرة تقنياً بعد وقوع الحادث.","keywords":["إدارة المخاطر","قياس الأداء","سياسة","مؤشر"]}]'::jsonb, 'published'),
  ('cs-q1-15', 'cs-q1', 'cs-l1', 'open', 'hard', 'ناقش لماذا لا تكفي الحلول التقنية وحدها لحماية المؤسسات من التهديدات السيبرانية، مع الإشارة إلى دور السياسات والوعي البشري ودور القيادة العليا في اتخاذ القرار.', 'مقالي', 'نقاط للتوجيه: أغلب الحوادث تبدأ بخطأ بشري لا بثغرة تقنية بحتة؛ الحلول التقنية بلا سياسات وتدريب وقيادة تبقى غير مكتملة، وهذا هو جوهر الربط بين الأمن السيبراني والحوكمة.', NULL, '[{"text":"نقاط للتوجيه: أغلب الحوادث تبدأ بخطأ بشري لا بثغرة تقنية بحتة (تصيد، كلمات مرور ضعيفة)؛ الحلول التقنية بلا سياسات وتدريب تبقى غير مكتملة؛ القيادة العليا مسؤولة عن اعتماد السياسات وتخصيص الموارد وربط الأمن بأهداف المؤسسة، وهذا ما لا تستطيع أي أداة تقنية فعله بمفردها.","keywords":["وعي بشري","سياسات","قيادة عليا","حوكمة"]}]'::jsonb, 'published'),
  ('cs-q1-16', 'cs-q1', 'cs-l3', 'mcq', 'easy', 'ما الوظيفة السادسة التي استُحدثت في إطار NIST CSF 2.0؟', NULL, 'الحوكمة (Govern) هي الوظيفة المستحدثة في CSF 2.0، وأصبحت وظيفة مستقلة ومركزية تُوجّه الوظائف الخمس الأخرى.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-17', 'cs-q1', 'cs-l3', 'tf', 'medium', 'في النسخة السابقة CSF 1.1، كانت عناصر الحوكمة مبعثرة ضمن وظيفة التعرّف (ID.GV).', NULL, 'صحيح؛ أدركت NIST لاحقاً أن الأمن السيبراني مسؤولية قيادية عليا لا مجرد مهمة تقنية، فأفردت الحوكمة كوظيفة مستقلة في CSF 2.0.', 'true'::jsonb, NULL, 'published'),
  ('cs-q1-18', 'cs-q1', 'cs-l3', 'fill', 'medium', 'الحد الأقصى للانحراف المقبول عن شهية المخاطر المعتمدة يسمّى ............', NULL, 'سقف التحمل (Risk Tolerance) يحدد الحد الأقصى للانحراف المقبول عن شهية المخاطر (Risk Appetite) التي تعتمدها الإدارة العليا.', '["سقف التحمل","سقف تحمل المخاطر"]'::jsonb, NULL, 'published'),
  ('cs-q1-19', 'cs-q1', 'cs-l3', 'match', 'hard', 'طابق كل فئة من فئات وظيفة الحوكمة (GV) بمضمونها الأساسي.', NULL, 'الفئات الست لوظيفة الحوكمة تغطي السياق التنظيمي، إدارة المخاطر، الأدوار والمسؤوليات، السياسات، الرقابة، وسلسلة التوريد.', NULL, NULL, 'published'),
  ('cs-q1-20', 'cs-q1', 'cs-l3', 'order', 'hard', 'رتّب مستويات تطبيق الإطار (Implementation Tiers) من الأدنى نضجاً إلى الأعلى.', NULL, 'تبدأ المستويات من الممارسات العشوائية غير المدوّنة (جزئي) وتنتهي بالاستجابة الديناميكية والتعلم المستمر من التهديدات (متكيف).', NULL, NULL, 'published'),
  ('cs-q1-21', 'cs-q1', 'cs-l3', 'mcq', 'medium', 'من الجهة التي تعتمد الاستراتيجية وتُقرّ شهية المخاطر السيبرانية بحسب فئة GV.RR؟', NULL, 'مجلس الإدارة والقيادة العليا هما من يعتمد الاستراتيجية ويُقرّ شهية المخاطر ويوفّر الموارد، بينما ينفّذ CISO البرنامج الأمني تشغيلياً.', '1'::jsonb, NULL, 'published'),
  ('cs-q1-22', 'cs-q1', 'cs-l3', 'mcq', 'easy', 'في أي عام صدرت النسخة 2.0 من إطار NIST CSF؟', NULL, 'صدرت النسخة 2.0 عام 2024 وشكّلت نقلة نوعية بتوسيع نطاق التطبيق واستحداث وظيفة الحوكمة.', '3'::jsonb, NULL, 'published'),
  ('cs-q1-23', 'cs-q1', 'cs-l3', 'tf', 'medium', 'أصبحت سلسلة التوريد والموردون الخارجيون من أكبر متجهات الهجوم (Attack Vectors) مع اعتماد المؤسسات على السحابة.', NULL, 'صحيح؛ ولهذا خُصصت فئة GV.SC لإدارة مخاطر سلسلة التوريد عبر تقييم الموردين والمراقبة المستمرة وخطط الطوارئ المشتركة.', 'true'::jsonb, NULL, 'published'),
  ('cs-q1-24', 'cs-q1', 'cs-l3', 'mcq', 'hard', 'ما الفرق بين «الملف الحالي» و«الملف المستهدف» في أدوات تطبيق الإطار؟', NULL, 'مقارنة الملف الحالي (الوضع الفعلي الراهن) بالملف المستهدف (الأهداف المطلوبة بناءً على شهية المخاطر) هي أساس تحليل الفجوة وبناء خارطة الطريق.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-1', 'ip-q1', 'ip-l1', 'mcq', 'easy', 'ما الفرق بين الاختراع والابتكار؟', NULL, 'الاختراع يقف عند حدّ الفكرة أو النموذج، بينما الابتكار هو تطبيقها فعلياً لتحقيق قيمة.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-2', 'ip-q1', 'ip-l2', 'tf', 'easy', 'توسيع نطاق المشروع دون تعديل الزمن والكلفة ممارسة سليمة تزيد قيمة المشروع.', NULL, 'هذا هو زحف النطاق، وهو من أشيع أسباب تعثّر المشاريع لأنه يخلّ بتوازن القيود الثلاثية.', 'false'::jsonb, NULL, 'published'),
  ('ip-q1-3', 'ip-q1', 'ip-l2', 'fill', 'medium', 'الوثيقة التي تعتمد انطلاق المشروع وتحدّد هدفه ونطاقه وأصحاب المصلحة تسمّى ............ المشروع.', NULL, 'ميثاق المشروع (Project Charter) هو وثيقة الاعتماد الرسمي لانطلاق المشروع.', '["ميثاق","ميثاق المشروع"]'::jsonb, NULL, 'published'),
  ('ip-q1-4', 'ip-q1', 'ip-l2', 'match', 'medium', 'طابق كل مرحلة من مراحل المشروع بنشاطها الأبرز.', NULL, 'كل مرحلة من مراحل دورة حياة المشروع لها مخرجات وأنشطة مميّزة لها.', NULL, NULL, 'published'),
  ('ip-q1-5', 'ip-q1', 'ip-l2', 'order', 'hard', 'رتّب مراحل دورة حياة المشروع بالترتيب الصحيح.', NULL, 'الترتيب المعتمد: البدء ← التخطيط ← التنفيذ ← المراقبة والتحكم ← الإغلاق.', NULL, NULL, 'published'),
  ('ip-q1-6', 'ip-q1', 'ip-l2', 'mcq', 'hard', 'مشروع رقمي متطلباته متغيّرة باستمرار ويحتاج تسليماً مبكراً للقيمة. أي منهج أنسب؟', NULL, 'المنهج الرشيق يعمل بدورات قصيرة تسمح باستيعاب التغيّر وتسليم قيمة مبكرة ومتكررة.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-7', 'ip-q1', 'ip-l1', 'mcq', 'medium', 'الفرق الجوهري بين الاختراع والابتكار هو أن الابتكار:', NULL, 'الابتكار يتجاوز مجرد الفكرة أو الاختراع إلى تحويله لقيمة فعلية قابلة للقياس.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-8', 'ip-q1', 'ip-l1', 'mcq', 'medium', '«ابتكار نموذج الأعمال» يعني تحديدًا:', NULL, 'ابتكار نموذج الأعمال يتعلق تحديدًا بطريقة تحقيق الإيرادات وتقديم القيمة، لا بالمنتج أو الهيكل وحدهما.', '2'::jsonb, NULL, 'published'),
  ('ip-q1-9', 'ip-q1', 'ip-l1', 'mcq', 'medium', 'أي مما يلي ليس من مكونات الاقتصاد الرقمي بحسب المحاضرة؟', NULL, 'الاقتصاد الرقمي يعتمد على الأسواق والمنصات الإلكترونية، لا الأسواق المكانية التقليدية حصرًا كما في الاقتصاد التقليدي.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-10', 'ip-q1', 'ip-l1', 'mcq', 'medium', 'من مراحل المشروع الرقمي، تأتي «دراسة الجدوى» مباشرة بعد:', NULL, 'الترتيب: تحديد المشكلة ← توليد الفكرة ← دراسة الجدوى ← النموذج الأولي...', '1'::jsonb, NULL, 'published'),
  ('ip-q1-11', 'ip-q1', 'ip-l2', 'mcq', 'medium', 'منهجية Agile تعتمد بصورة أساسية على:', NULL, 'Agile تقوم على التطوير المرحلي (كما في Scrum وSprints) وسرعة الاستجابة للتغيير.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-12', 'ip-q1', 'ip-l3', 'mcq', 'medium', '«الابتكار المفتوح» (Open Innovation) يعني:', NULL, 'الابتكار المفتوح يوسّع مصادر الابتكار لتشمل الجامعات والحاضنات والعملاء والمستثمرين، لا الاعتماد الداخلي الحصري.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-13', 'ip-q1', 'ip-l1', 'mcq', 'medium', 'في نموذج «فكرة ← ابتكار ← فرصة اقتصادية ← مشروع رقمي ← قيمة اقتصادية ← نمو وتوسع»، ما الذي يربط الابتكار بريادة الأعمال؟', NULL, 'الابتكار يولّد الفرصة، وريادة الأعمال هي التي تستثمر هذه الفرصة وتحوّلها إلى مشروع فعلي.', '0'::jsonb, NULL, 'published'),
  ('ip-q1-14', 'ip-q1', 'ip-l1', 'tf', 'medium', 'يعني الابتكار مجرد إنتاج فكرة جديدة ومبتكرة دون الحاجة لتطبيقها.', NULL, 'هذا تعريف الإبداع لا الابتكار؛ الابتكار يتطلب تحويل الفكرة إلى قيمة قابلة للقياس.', 'false'::jsonb, NULL, 'published'),
  ('ip-q1-15', 'ip-q1', 'ip-l1', 'tf', 'medium', 'من خصائص المشاريع الرقمية ارتفاع مستوى عدم اليقين وسرعة التغيّر.', NULL, 'هذا مطابق لما ورد في المحور الخامس عن خصائص المشاريع الرقمية.', 'true'::jsonb, NULL, 'published'),
  ('ip-q1-16', 'ip-q1', 'ip-l2', 'tf', 'medium', 'Scrum منهجية بديلة تمامًا عن Agile ولا علاقة بينهما.', NULL, 'Scrum هو من أشهر تطبيقات منهجية Agile، وليس بديلًا مستقلًا عنها.', 'false'::jsonb, NULL, 'published'),
  ('ip-q1-17', 'ip-q1', 'ip-l1', 'tf', 'medium', 'يمكن للمشاريع الصغيرة الوصول إلى أسواق واسعة بفضل انخفاض تكاليف التكنولوجيا الرقمية.', NULL, 'هذا من أبرز أدوار الابتكار في دعم ريادة الأعمال بحسب المحاضرة.', 'true'::jsonb, NULL, 'published'),
  ('ip-q1-18', 'ip-q1', 'ip-l1', 'tf', 'medium', 'ينبغي النظر إلى الابتكار الرقمي بوصفه وسيلة لزيادة الأرباح فقط، بمعزل عن الاستدامة.', NULL, 'المحاضرة تؤكد أن الابتكار أداة لتحقيق الاستدامة الاقتصادية والاجتماعية والبيئية، لا الربح فقط.', 'false'::jsonb, NULL, 'published'),
  ('ip-q1-19', 'ip-q1', 'ip-l1', 'open', 'hard', 'شركة ناشئة عراقية طوّرت تطبيقًا للدفع الإلكتروني، لكنها لم تحدد بوضوح كيف ستحقق الإيرادات من التطبيق (عمولة، اشتراك، إعلانات...). في أي محور من محاور المشروع الرقمي يقع هذا القصور، وكيف يُعالَج؟', 'سيناريو', 'القصور يقع في مرحلة دراسة الجدوى، وتحديدًا الجدوى الاقتصادية ونموذج الأعمال (كيف يحقق المشروع الإيرادات). يُعالَج بإعادة دراسة نموذج الأعمال وتحديد مصدر إيرادات واضح قبل الانتقال لمرحلة التنفيذ والإطلاق.', NULL, '[{"text":"القصور يقع في مرحلة دراسة الجدوى، وتحديدًا الجدوى الاقتصادية ونموذج الأعمال (كيف يحقق المشروع الإيرادات). يُعالَج بإعادة دراسة نموذج الأعمال وتحديد مصدر إيرادات واضح قبل الانتقال لمرحلة التنفيذ والإطلاق.","keywords":[]}]'::jsonb, 'published'),
  ('ip-q1-20', 'ip-q1', 'ip-l2', 'open', 'hard', 'مؤسسة حكومية تريد تطوير خدمة رقمية جديدة، وتتردد بين استخدام التخطيط التقليدي طويل الأجل أو منهجية Agile. ما العوامل التي يجب أن تحدد اختيارها؟', 'سيناريو', 'يعتمد الاختيار على مدى استقرار المتطلبات ودرجة التغيّر المتوقعة: إن كانت بيئة العمل سريعة التغيّر وتحتاج تفاعلًا مستمرًا مع المستخدمين فمنهجية Agile أنسب، أما إذا كانت المتطلبات واضحة ومستقرة ولا تحتمل تعديلات متكررة فقد يكون التخطيط التقليدي كافيًا.', NULL, '[{"text":"يعتمد الاختيار على مدى استقرار المتطلبات ودرجة التغيّر المتوقعة: إن كانت بيئة العمل سريعة التغيّر وتحتاج تفاعلًا مستمرًا مع المستخدمين فمنهجية Agile أنسب، أما إذا كانت المتطلبات واضحة ومستقرة ولا تحتمل تعديلات متكررة فقد يكون التخطيط التقليدي كافيًا.","keywords":[]}]'::jsonb, 'published'),
  ('ip-q1-21', 'ip-q1', 'ip-l3', 'open', 'hard', 'ناقش كيف يمكن للجامعات أن تسهم في دعم الاقتصاد الرقمي من خلال مفهوم الابتكار المفتوح.', 'مقالي', 'نقاط للتوجيه: دور الجامعة كمصدر معرفة وبحث، وتحويل نتائج البحث العلمي إلى مشاريع وشركات ناشئة، والتعاون مع الحاضنات والمستثمرين والعملاء ضمن منظومة ابتكار مفتوح.', NULL, '[{"text":"نقاط للتوجيه: دور الجامعة كمصدر معرفة وبحث، وتحويل نتائج البحث العلمي إلى مشاريع وشركات ناشئة، والتعاون مع الحاضنات والمستثمرين والعملاء ضمن منظومة ابتكار مفتوح.","keywords":[]}]'::jsonb, 'published'),
  ('ip-q1-22', 'ip-q1', 'ip-l1', 'open', 'hard', 'اختر قطاعًا عراقيًا واحدًا من القطاعات الواردة في المحور الثاني عشر، واقترح مشروعًا رقميًا مبتكرًا له، مستخدمًا نموذج التحليل المتكامل (المشكلة ← الفكرة ← الابتكار ← التكنولوجيا ← نموذج الأعمال ← المشروع ← السوق ← القيمة ← الاستدامة).', 'مقالي', 'نقاط للتوجيه: التزم بالترتيب المنطقي للنموذج، وحدد بوضوح المشكلة الواقعية في القطاع المختار قبل اقتراح الحل التقني، ثم اربط الحل بمصدر إيرادات وأثر اقتصادي مستدام.', NULL, '[{"text":"نقاط للتوجيه: التزم بالترتيب المنطقي للنموذج، وحدد بوضوح المشكلة الواقعية في القطاع المختار قبل اقتراح الحل التقني، ثم اربط الحل بمصدر إيرادات وأثر اقتصادي مستدام.","keywords":[]}]'::jsonb, 'published'),
  ('ip-q1-23', 'ip-q1', 'ip-l3', 'mcq', 'medium', 'ما الفرق الجوهري بين الابتكار التدريجي والابتكار الجذري؟', NULL, 'التدريجي يحسّن القائم بمخاطر منخفضة، بينما الجذري يحدث نقلة نوعية أو تدميراً خلّاقاً بمخاطر مرتفعة جداً وعدم يقين مرتفع.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-24', 'ip-q1', 'ip-l3', 'tf', 'medium', 'مفهوم «التدمير الخلّاق» الذي صاغه شومبيتر يصف كيف يزيح الابتكار الجذري المنتجات والتقنيات القائمة كلياً.', NULL, 'التدمير الخلّاق (Creative Destruction) هو بالضبط وصف شومبيتر لإحداث الابتكار الجذري إزاحة تامة لما هو قائم.', 'true'::jsonb, NULL, 'published'),
  ('ip-q1-25', 'ip-q1', 'ip-l3', 'fill', 'medium', 'الوحدات التنظيمية المستقلة التي تُستخدم لفصل الابتكار الجذري عن الضغوط التشغيلية اليومية تسمّى المنظمات ............', NULL, 'المنظمات الاستضمارية (Ambidextrous Organizations) تفصل وحدات الابتكار الجذري عن العمليات التشغيلية اليومية للحد من تضارب الأولويات.', '["الاستضمارية","استضمارية"]'::jsonb, NULL, 'published'),
  ('ip-q1-26', 'ip-q1', 'ip-l3', 'match', 'medium', 'طابق كل بُعد من أبعاد الابتكار المفتوح بتعريفه.', NULL, 'الأبعاد الثلاثة لنموذج تشيسبرو تحدد اتجاه تدفق المعرفة والتقنية بين المنظمة والبيئة الخارجية.', NULL, NULL, 'published'),
  ('ip-q1-27', 'ip-q1', 'ip-l3', 'mcq', 'medium', 'من صاغ نموذج الابتكار المفتوح (Open Innovation)؟', NULL, 'البروفيسور هنري تشيسبرو (Henry Chesbrough) هو من صاغ نموذج الابتكار المفتوح.', '1'::jsonb, NULL, 'published'),
  ('ip-q1-28', 'ip-q1', 'ip-l3', 'mcq', 'medium', 'نموذج الابتكار المستمر يستمد أصوله بشكل خاص من فلسفات:', NULL, 'نموذج الابتكار المستمر مستمد من Kaizen والرشاقة المؤسسية (Organizational Agility) والإدارة الهزيلة (Lean Management).', '1'::jsonb, NULL, 'published'),
  ('ip-q1-29', 'ip-q1', 'ip-l3', 'tf', 'medium', 'في نموذج الابتكار المستمر، الابتكار مسؤولية قسم البحث والتطوير وحده دون بقية العاملين.', NULL, 'على العكس؛ نموذج الابتكار المستمر يشرك جميع العاملين بمختلف المستويات الإدارية في ممارسة الابتكار اليومية.', 'false'::jsonb, NULL, 'published'),
  ('ip-q1-30', 'ip-q1', 'ip-l3', 'order', 'hard', 'رتّب هذه الاستراتيجيات حسب المنطق الذي تربط به المحاضرة بين مستوى المخاطرة والأفق الزمني، من الأقل مخاطرة (الأجل الأقصر) إلى الأعلى مخاطرة (الأجل الأطول).', NULL, 'الشركات الناجحة تستخدم التدريجي والمستمر للربحية القصيرة الأجل بمخاطر أقل، وتستعين بالمفتوح لتسريع الابتكار، بينما تعتمد على الجذري ذي المخاطر الأعلى لضمان البقاء طويل الأجل.', NULL, NULL, 'published'),
  ('ip-q1-31', 'ip-q1', 'ip-l3', 'open', 'hard', 'شركة اتصالات كبرى تريد إطلاق خدمة جديدة، وتتردد بين تطوير الخدمة داخلياً بالكامل أو الشراكة مع شركة ناشئة تملك التقنية اللازمة. أي بُعد من أبعاد الابتكار المفتوح ينطبق على خيار الشراكة، ولماذا قد يكون أسرع من التطوير الداخلي الكامل؟', 'سيناريو', 'ينطبق بُعد الابتكار من الخارج إلى الداخل (Inbound)، وهو أسرع لأنه يستفيد من تقنية ناضجة لدى الشريك بدل بناء القدرة من الصفر داخلياً.', NULL, '[{"text":"ينطبق بُعد الابتكار من الخارج إلى الداخل (Inbound Open Innovation)، إذ تستقطب الشركة تقنية جاهزة من طرف خارجي بدل تطويرها من الصفر. هذا أسرع لأنه يتجنب دورة البحث والتطوير الداخلية الكاملة ويستفيد من نضج التقنية لدى الشريك.","keywords":["Inbound","خارج إلى الداخل","شراكة"]}]'::jsonb, 'published'),
  ('rm-q1-1', 'rm-q1', 'rm-l1', 'mcq', 'easy', 'ما الفرق بين الخطر والمشكلة؟', NULL, 'الخطر احتمالي مستقبلي يُدار استباقياً، أما المشكلة فواقعة حاليّة تُعالَج آنياً.', '1'::jsonb, NULL, 'published'),
  ('rm-q1-2', 'rm-q1', 'rm-l1', 'tf', 'easy', 'جميع المخاطر سلبية بطبيعتها ولا يمكن أن تمثّل فرصة.', NULL, 'الخطر أثر محتمل على الأهداف، وقد يكون إيجابياً؛ ولذلك تُدار الفرص ضمن إدارة المخاطر.', 'false'::jsonb, NULL, 'published'),
  ('rm-q1-3', 'rm-q1', 'rm-l1', 'fill', 'medium', 'يُحسب مستوى الخطر بحاصل ضرب الاحتمال في ............', NULL, 'معادلة الخطر الأساسية: مستوى الخطر = الاحتمال × الأثر.', '["الأثر","الاثر","التأثير"]'::jsonb, NULL, 'published'),
  ('rm-q1-4', 'rm-q1', 'rm-l2', 'match', 'medium', 'طابق كل استراتيجية معالجة بمثالها.', NULL, 'الاستراتيجيات الأربع تُختار وفق مستوى الخطر وكلفة المعالجة وشهية المخاطر.', NULL, NULL, 'published'),
  ('rm-q1-5', 'rm-q1', 'rm-l1', 'order', 'hard', 'رتّب مراحل دورة إدارة المخاطر بالترتيب الصحيح.', NULL, 'الدورة تبدأ بتحديد المخاطر وتنتهي بالمراقبة والمراجعة المستمرة التي تغذّي الدورة من جديد.', NULL, NULL, 'published'),
  ('rm-q1-6', 'rm-q1', 'rm-l2', 'mcq', 'hard', 'خطر احتماله منخفض جداً وأثره كارثي على استمرارية الخدمة. ما المعالجة الأنسب؟', NULL, 'المخاطر منخفضة الاحتمال عالية الأثر تُعالج بخطط الاستمرارية والطوارئ لأن أثرها يهدّد الأهداف الأساسية.', '2'::jsonb, NULL, 'published'),
  ('rm-q1-7', 'rm-q1', 'rm-l1', 'mcq', 'medium', 'بحسب المعيار الدولي ISO 31000، ما تعريف الخطر؟', NULL, 'يعرّف ISO 31000 الخطر بأنه «أثر عدم اليقين في الأهداف» — تعريف أوسع وأدق من الاقتصار على الاحتمال × الأثر، لأنه يربط الخطر بالهدف صراحة.', '1'::jsonb, NULL, 'published'),
  ('rm-q1-8', 'rm-q1', 'rm-l1', 'match', 'hard', 'طابق كل عنصر من عناصر الخطر الثلاثة بتعريفه.', NULL, 'المُخطِر لا يملكه المدير، أما التعرّض وقابلية التأثر فهما إلى حد كبير ضمن نطاق قراراته — وهنا تكمن الفائدة العملية لهذا التفكيك.', NULL, NULL, 'published'),
  ('rm-q1-9', 'rm-q1', 'rm-l1', 'tf', 'medium', 'بحسب فرانك نايت، «المخاطرة» و«عدم اليقين» مترادفان تماماً.', NULL, 'ميّز نايت بينهما: المخاطرة حالة يمكن فيها تقدير الاحتمالات اعتماداً على بيانات متكررة، أما عدم اليقين فحالة لا تتوافر فيها معلومات كافية تسمح بذلك.', 'false'::jsonb, NULL, 'published'),
  ('rm-q1-10', 'rm-q1', 'rm-l1', 'mcq', 'hard', 'ماذا أسمى دانيال إلسبرغ الحالة التي يختلف فيها الخبراء في تقدير الاحتمالات نفسها لا في النتائج فقط؟', NULL, 'الغموض (Ambiguity) بحسب إلسبرغ هو اختلاف الخبراء في تقدير الاحتمالات نفسها، والناس يميلون لتجنّب القرارات ذات الاحتمالات غير الواضحة حتى لو تقاربت النتائج المتوقعة حسابياً.', '2'::jsonb, NULL, 'published'),
  ('rm-q1-11', 'rm-q1', 'rm-l1', 'fill', 'medium', 'أخذ خطر قُدِّر مداه ووُضع أمام معيار وقورن ببدائل ووُثِّق يسمّى ............', NULL, 'المخاطرة المحسوبة تختلف عن التهوّر (خطر غير مقدَّر) وعن الجمود (امتناع عن خطر مقدَّر خوفاً من المساءلة) — والفرق بينها جودة عملية القرار لا النتيجة.', '["المخاطرة المحسوبة","مخاطرة محسوبة"]'::jsonb, NULL, 'published'),
  ('rm-q1-12', 'rm-q1', 'rm-l1', 'mcq', 'medium', 'ما الفرق الجوهري بين سؤال «الرقابة الداخلية» وسؤال «إدارة المخاطر»؟', NULL, 'كل وظيفة تجيب عن سؤال مختلف: إدارة المخاطر (ماذا نقرر؟)، الرقابة الداخلية (هل الضوابط تعمل؟)، التدقيق الداخلي (هل ما يُقال عن الأداء صحيح؟)، الامتثال (هل نلتزم بالمتطلبات؟).', '1'::jsonb, NULL, 'published'),
  ('rm-q1-13', 'rm-q1', 'rm-l1', 'order', 'hard', 'رتّب هذه الوصلات من حلقة الخطر–القرار بالترتيب الصحيح.', NULL, 'حلقة الخطر–القرار سلسلة دائرية: يجب أن تتحول المعرفة إلى معيار، ثم إلى بدائل، ثم إلى قرار وتنفيذ ومتابعة تغذّي التأطير من جديد — وأضعف وصلة تحدد قوة السلسلة كلها.', NULL, NULL, 'published'),
  ('rm-q1-14', 'rm-q1', 'rm-l1', 'mcq', 'easy', 'موقف وقع بالفعل، وتجاوز أثره المعتاد، ويحتاج استجابة سريعة تحت ضغط الوقت — ما هذا؟', NULL, 'الأزمة موقف وقع بالفعل ويهدد أموراً جوهرية تحت ضغط الوقت، بخلاف المشكلة (وقعت وتحتاج معالجة) والخطر (لم يقع بعد).', '2'::jsonb, NULL, 'published'),
  ('rm-q1-15', 'rm-q1', 'rm-l1', 'open', 'hard', 'جهة حكومية تملك سجل مخاطر مكتملاً بأكثر من خمسين خطراً موثقاً بالألوان والدرجات، لكن لا أحد يتذكر قراراً واحداً تغيّر بسببه خلال العام الماضي. بأي «وصلة» من حلقة الخطر–القرار يبدو أن الانكسار وقع على الأرجح، ولماذا لا يكفي اكتمال السجل وحده؟', 'سيناريو', 'اكتمال سجل المخاطر لا يعني أن المنظومة فعّالة؛ فقد تنتج امتثالاً أكثر مما تنتج قراراً — والمعيار الحقيقي هو عدد القرارات التي تغيّرت فعلياً بسبب تحليل المخاطر (اختبار الأثر القراري).', NULL, '[{"text":"الانكسار على الأرجح في وصلة المعيار أو توليد البدائل: المعرفة موجودة (السجل مكتمل)، لكن غياب حد معلن وملزم لما تقبله المؤسسة يمنع تحويل المعرفة إلى بدائل ثم قرار. اكتمال السجل لا يكفي لأن اختبار الأثر القراري هو المعيار الحقيقي: كم قراراً تغيّر فعلياً، لا كم خطراً سُجِّل.","keywords":["المعيار","اختبار الأثر القراري","حلقة الخطر-القرار","البدائل"]}]'::jsonb, 'published')
